 streams:['streams','GTA Streams','Browse member-submitted Grand Theft Auto stream links. Availability is shown only when a member has added a link.'],
 messages:['messages','Messages','Private conversations for signed-in members. Only participants can read them.'],
 notifications:['notifications','Notifications','Connection requests, replies, mentions, invitations, and moderation updates for your account.'],
 challenges:['challenges','GTA Challenges & leaderboards','Browse community challenges and player-entered results. Rankings are not official game statistics.'],
 history:['history','GTA Achievements & history','Track your Grand Theft Auto milestones and gaming history. User-entered information is clearly marked.'],
 settings:['settings','Settings','Manage profile, privacy, account, and notification preferences.'],
