const state=(heading,copy,extra='')=>`<div class="state info"><h3>${escapeHTML(heading)}</h3><p>${escapeHTML(copy)}</p>${extra}</div>`;
const infoRow=(title,description,iconName='◈',meta='')=>`<div class="data-row"><span class="pill">${icon(iconName, 'data-row-icon')}</span><span class="grow"><h3>${escapeHTML(title)}</h3><p>${escapeHTML(description)}</p></span>${meta?`<span class="muted tiny">${escapeHTML(meta)}</span>`:''}</div>`;
const error=(message)=>`<div class="state error"><h3>Something went wrong</h3><p>${escapeHTML(message)}</p><button class="btn" onclick="location.reload()">Retry</button></div>`;
const success=(message)=>`<div class="state success" role="status"><h3>Saved</h3><p>${escapeHTML(message)}</p></div>`;
const date=(s)=>s?new Date(s).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}):'';
const initials=(s='V')=>escapeHTML(String(s).slice(0,1).toUpperCase());
const playerRow=(profile,description='GameVault player')=>`<a class="data-row" href="/pages/profile.html?username=${encodeURIComponent(profile.username||'')}">${avatarMarkup(profile,'gv-player-avatar',`${profile.display_name||profile.username||'Player'} avatar`)}<span class="grow"><h3>${escapeHTML(profile.display_name||profile.username||'GameVault player')}</h3><p>${escapeHTML(description)}</p></span>${icon('arrow-right','row-arrow')}</a>`;
const gameArt=(slug)=>{const game=catalog.find(item=>item.slug===slug);return game?.game_image_path||game?.cover_path||game?.artwork_path||''};
function safeExternalHref(value){try{const url=new URL(value);return url.protocol==='https:'?url.toString():null}catch{return null}}
function safeInternalHref(value){return typeof value==='string'&&value.startsWith('/')&&!value.startsWith('//')?value:null}
const socialNetworks=[['discord','Discord',['discord.gg','discord.com']],['twitch','Twitch',['twitch.tv']],['youtube','YouTube',['youtube.com','youtu.be']],['instagram','Instagram',['instagram.com']],['x','X',['x.com','twitter.com']]];
function validSocialURL(key,value){if(!value)return true;try{const url=new URL(value),network=socialNetworks.find(x=>x[0]===key);return url.protocol==='https:'&&network?.[2].some(host=>url.hostname===host||url.hostname.endsWith('.'+host))}catch{return false}}
function renderSocialMenu(links={}){const items=socialNetworks.map(([key,label])=>[key,label,links?.[key]]).filter(([key,,url])=>url&&validSocialURL(key,url));return items.length?`<details class="social-links-menu"><summary class="btn">Social links · ${items.length}</summary><div class="social-links-panel">${items.map(([key,label,url])=>`<a class="social-link social-${key}" href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer"><span class="social-mark">${icon(key, 'social-mark-icon')}</span>${escapeHTML(label)} ${icon('external-link')}</a>`).join('')}</div></details>`:''}
function entry(feature,run,{backend=true}={}){const [page,title,description]=pageInfo[feature];mountPage({page,title,description,backend,run});}
function authPrompt(next=location.pathname){return `<a class="btn btn-primary" href="/pages/login.html?next=${encodeURIComponent(next)}">Sign in</a> <a class="btn" href="/pages/signup.html">Create account</a>`}
async function currentUser(configured,root,{redirect=false}={}){if(!configured){root.insertAdjacentHTML('beforeend',state('Supabase is needed for this account action','Connect GameVault to Supabase before using account-specific features.'));return null}const {user,error:authError}=await requireUser({redirect});if(authError)throw authError;if(!user){if(!redirect)root.insertAdjacentHTML('beforeend',state('Sign in required','Sign in to see data that belongs to your account.',authPrompt()));return null}return user}
function allowedFile(file,video=true){const mime=['image/jpeg','image/png','image/webp','image/gif',...(video?['video/mp4','video/webm']:[])];return file&&mime.includes(file.type)&&file.size<=(video?50:5)*1024*1024}
function galleryCard(item){const alt=`${item.name}, ${item.category}`;const ui=item.category.includes('Interface');return `<article class="surface asset-card ${ui?'asset-ui':''}"><a class="asset-thumb" href="${item.src}" target="_blank" rel="noopener" aria-label="Open ${escapeHTML(item.path)}"><img loading="lazy" src="${item.src}" alt="${escapeHTML(alt)}"></a><div class="asset-meta"><strong>${escapeHTML(item.path)}</strong><span>${escapeHTML(item.category)}</span><span>${escapeHTML(item.purpose)}</span></div></article>`}
function commonFormMessage(el,message,kind='success'){el.innerHTML=`<div class="state ${kind}" role="status"><p>${escapeHTML(message)}</p></div>`}

async function loadPosts(container,communityId=null,communityIds=null,connectedAuthorIds=null){
  let q=supabase.from('posts').select('id,author_id,community_id,body,created_at,communities(name,slug)').order('created_at',{ascending:false}).limit(30);
  if(communityId)q=q.eq('community_id',communityId);
  else if(communityIds?.length&&connectedAuthorIds?.length)q=q.or(`community_id.in.(${communityIds.join(',')}),author_id.in.(${connectedAuthorIds.join(',')})`);
  else if(communityIds?.length)q=q.in('community_id',communityIds);
  else if(connectedAuthorIds?.length)q=q.in('author_id',connectedAuthorIds);
  const {data:posts,error:loadError}=await q;if(loadError)throw loadError;
  if(!posts?.length){container.innerHTML=state('No posts here yet','Real posts from community members will appear here after someone publishes them.');return}
  const authorIds=[...new Set(posts.map(p=>p.author_id))];const people=await supabase.from('profile_cards').select('id,username,display_name,avatar_url').in('id',authorIds);if(people.error)throw people.error;
  const profileById=new Map((people.data||[]).map(p=>[p.id,p]));
  const postIds=posts.map(p=>p.id);const [reactions,comments]=await Promise.all([
    supabase.from('post_reactions').select('post_id,user_id,reaction').in('post_id',postIds),
    supabase.from('comments').select('id,post_id,author_id,body,created_at').in('post_id',postIds).order('created_at',{ascending:true}).limit(100)
  ]);if(reactions.error)throw reactions.error;if(comments.error)throw comments.error;
  container.innerHTML=posts.map(post=>{const person=profileById.get(post.author_id);const postComments=(comments.data||[]).filter(c=>c.post_id===post.id);const count=(reactions.data||[]).filter(r=>r.post_id===post.id).length;const avatar=person?.avatar_url?`<img class="avatar-dot" src="${escapeHTML(person.avatar_url)}" alt="">`:`<span class="pill">${initials(person?.display_name||'V')}</span>`;return `<article class="surface post-card" data-post="${post.id}"><div class="row">${avatar}<div class="grow"><strong>${person?`<a href="/pages/profile.html?username=${encodeURIComponent(person.username)}">${escapeHTML(person.display_name||person.username)}</a>`:'GameVault member'}</strong><div class="muted tiny">${escapeHTML(post.communities?.name||'Community post')} · ${date(post.created_at)}</div></div>${post.communities?.slug?`<a class="pill" href="/pages/community.html?slug=${encodeURIComponent(post.communities.slug)}">Open community</a>`:''}</div><p>${escapeHTML(post.body)}</p><div class="row"><button class="btn react" data-id="${post.id}" aria-label="React to post">${icon('heart')} <span class="react-label">React</span> <span>${count}</span></button><button class="btn comment-toggle" data-id="${post.id}">${icon('comment')} Reply (${postComments.length})</button><button class="btn report-post" data-id="${post.id}">${icon('flag')} Report</button></div><div class="comments" id="comments-${post.id}">${postComments.map(c=>`<p class="tiny"><strong>Member</strong> · ${escapeHTML(c.body)}</p>`).join('')}<form class="comment-form row" data-id="${post.id}"><input class="field" name="body" maxlength="2000" placeholder="Write a reply…" required><button class="btn" type="submit">${icon('send')} Send</button></form></div></article>`}).join('');
  container.querySelectorAll('.react').forEach(button=>button.addEventListener('click',async()=>{const {data:{user}}=await getOptionalUser();if(!user){location.href='/pages/login.html';return}const postId=button.dataset.id;const existing=await supabase.from('post_reactions').select('post_id').eq('post_id',postId).eq('user_id',user.id).maybeSingle();if(existing.error){button.title=existing.error.message;return}if(existing.data){button.setAttribute('aria-pressed','true');button.querySelector('.react-label').textContent='Reacted';return}const {error:saveError}=await supabase.from('post_reactions').insert({post_id:postId,user_id:user.id,reaction:'like'});if(saveError)button.title=saveError.message;else{button.setAttribute('aria-pressed','true');button.querySelector('.react-label').textContent='Reacted';const countNode=button.querySelector('span:last-child');countNode.textContent=String(Number(countNode.textContent)+1)}}));
  container.querySelectorAll('.comment-toggle').forEach(button=>button.addEventListener('click',()=>{const box=container.querySelector(`#comments-${CSS.escape(button.dataset.id)}`);if(!box)return;box.classList.toggle('open');if(box.classList.contains('open'))box.querySelector('input')?.focus()}));
  container.querySelectorAll('.report-post').forEach(button=>button.addEventListener('click',async()=>{const {data:{user}}=await getOptionalUser();if(!user){location.href='/pages/login.html';return}const reason=prompt('Briefly describe the concern with this post:');if(!reason?.trim())return;const {error:reportError}=await supabase.from('moderation_reports').insert({reporter_id:user.id,subject_type:'post',subject_id:button.dataset.id,reason:reason.trim()});if(reportError)alert('Report could not be sent: '+reportError.message);else alert('Report sent to GameVault moderation.')}));
  container.querySelectorAll('.comment-form').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();const {data:{user}}=await getOptionalUser();if(!user){location.href='/pages/login.html';return}const body=new FormData(form).get('body').toString().trim();const {error:saveError}=await supabase.from('comments').insert({post_id:form.dataset.id,author_id:user.id,body});if(saveError)commonFormMessage(form,saveError.message,'error');else location.reload()}));
}

function home(){
 entry('home',async({root,configured})=>{
  const featured = catalog.find(game => game.slug === 'grand-theft-auto-vi') || catalog[0];
  const spotlightHref = `/games/${encodeURIComponent(featured.slug)}/`;
  const platforms = (featured.platforms || []).slice(0,3).map(escapeHTML).join(' · ');
  const featuredArt = featured.cover_path ? `<img class="vault-spotlight-art" src="${escapeHTML(featured.cover_path)}" alt="" fetchpriority="high" decoding="async" referrerpolicy="no-referrer">` : '<div class="gv-sunset-art" aria-hidden="true"></div>';
  const featuredSource = featured.cover_path ? '<small class="vault-art-note"><a href="https://www.rockstargames.com/VI/media" target="_blank" rel="noopener noreferrer">Official Rockstar media · local prototype</a></small>' : '<small class="vault-art-note">Original GameVault artwork · not an official game cover</small>';
  const highlights = ['grand-theft-auto-v','grand-theft-auto-vice-city','grand-theft-auto-san-andreas','grand-theft-auto-vi'].map(slug => catalog.find(game => game.slug === slug)).filter(Boolean);
  root.insertAdjacentHTML('beforeend',`<h1 class="sr-only">GameVault game dashboard</h1><section class="vault-spotlight" aria-labelledby="vault-spotlight-title">${featuredArt}<div class="vault-spotlight-shade"></div><div class="vault-spotlight-content"><p class="eyebrow">GameVault CATALOG SPOTLIGHT <span>·</span> GTA WORLDWORK</p><span class="vault-kicker">${escapeHTML(featured.genre || 'Game catalog')}</span><h2 id="vault-spotlight-title">${escapeHTML(featured.title)}</h2><p class="vault-spotlight-description">${escapeHTML(featured.description || 'Explore this title in the GameVault game directory.')}</p><p class="vault-platforms">${platforms || 'Platform details are listed on the game page'}</p><div class="vault-spotlight-actions"><a class="btn btn-primary" href="${spotlightHref}">View game <span aria-hidden="true">↗</span></a><a class="btn" href="/games/index.html">Explore all games <span aria-hidden="true">→</span></a></div>${featuredSource}</div><a class="vault-spotlight-hit" href="${spotlightHref}" aria-label="Open ${escapeHTML(featured.title)} game page"></a></section>
  <section class="vault-library"><div class="home-section-heading"><div><p class="eyebrow">YOUR COLLECTION</p><h2>Your games</h2></div><a href="/games/library/">Open library <span aria-hidden="true">↗</span></a></div><div id="home-library-content"><div class="state loading">Loading your library status…</div></div></section>
  <section class="vault-catalog"><div class="home-section-heading"><div><p class="eyebrow">PICK YOUR NEXT WORLD</p><h2>Featured games</h2></div><a href="/games/index.html">Browse the full catalog <span aria-hidden="true">↗</span></a></div><div class="vault-game-grid">${highlights.map((game,index)=>{const art=game.game_image_path||game.cover_path||game.artwork_path;return `<a class="vault-game-card" href="/games/${encodeURIComponent(game.slug)}/"><span class="vault-game-art vault-art-${index+1}">${art ? `<img src="${escapeHTML(art)}" alt="" loading="lazy" decoding="async"${game.cover_path?' referrerpolicy="no-referrer"':''}>` : ''}<span>GTA WORLD</span></span><span class="vault-game-copy"><strong>${escapeHTML(game.title)}</strong><small>${escapeHTML(game.genre || 'Game listing')} · GameVault catalog</small><span class="vault-game-open">View game <i aria-hidden="true">↗</i></span></span></a>`}).join('')}</div><p class="vault-catalog-note">All game screenshots and the GTA VI cover shown here are local prototype assets with written permission pending. Catalog entries are curated listings, not publisher availability or activity data.</p></section>`);

  const library = root.querySelector('#home-library-content');
  let user = null;
  if(configured){const auth = await getOptionalUser();if(auth.error)throw auth.error;user=auth.data.user;}
  if(!configured){library.innerHTML=state('Connect your GameVault account','Your personal games, favorites, and play status will appear here once the GameVault Supabase project is configured. The game catalog is ready to browse.','<a class="btn btn-primary" href="/games/index.html">Browse games</a>');}
  else if(!user){library.innerHTML=state('Your collection starts here','Sign in to save games to your library. This page does not show sample players or sample collections.',authPrompt('/pages/home.html'));}
  else{
    const {data:rows,error:libraryError}=await supabase.from('user_games').select('game_id,is_favorite,is_currently_playing,added_at,games!inner(id,slug,title,genre,franchise)').eq('user_id',user.id).eq('games.franchise','grand-theft-auto').order('added_at',{ascending:false}).limit(6);
    if(libraryError)library.innerHTML=state('Your library could not load','Try again, or open the full game library to see the account status.','<a class="btn" href="/games/library/">Open game library</a>');
    else if(!rows?.length)library.innerHTML=state('Your GTA library is ready for its first title','Search the GameVault catalog and add the games you play.','<a class="btn btn-primary" href="/games/index.html">Find games to add</a>');
    else library.innerHTML=`<div class="vault-owned-grid">${rows.map(row=>`<article class="vault-owned-card"><div class="vault-owned-mark" aria-hidden="true">${initials(row.games?.title || 'G')}</div><div class="vault-owned-copy"><a href="/games/${encodeURIComponent(row.games?.slug || '')}/"><strong>${escapeHTML(row.games?.title || 'Game')}</strong></a><small>${escapeHTML(row.games?.genre || 'Game')}</small></div>${row.is_currently_playing?'<span class="vault-status">Playing</span>':row.is_favorite?'<span class="vault-status favorite">Favorite</span>':''}</article>`).join('')}</div>`;
  }

  const feedSection=`<section class="home-feed-section"><div class="home-section-heading"><div><p class="eyebrow">FROM YOUR COMMUNITY</p><h2>Your GameVault feed</h2></div><a href="/pages/communities.html">Find a squad ↗</a></div><div id="home-feed-content"></div></section>`;
  root.insertAdjacentHTML('beforeend',feedSection);
  const feed=root.querySelector('#home-feed-content');
  if(!configured)feed.innerHTML=state('Community posts are waiting for Supabase','Connect the backend to load real posts from communities and connections.');
  else if(!user)feed.innerHTML=state('Sign in to see your feed','Your feed only shows real posts you are allowed to see.',authPrompt('/pages/home.html'));
  else{
    feed.innerHTML=`<form class="surface surface-pad form-stack" id="post-form"><label class="field-wrap">Share with a community<textarea class="textarea" name="body" maxlength="4000" required placeholder="What are you playing or creating?"></textarea></label><div class="row"><select class="select" name="community_id" required><option value="">Choose a community you joined</option></select><button class="btn btn-primary" type="submit">Post to community</button></div><div id="post-feedback"></div></form><div class="home-feed-list" id="feed-list"><div class="state loading">Loading posts…</div></div>`;
    const joined=await supabase.from('community_members').select('community_id,communities(id,name,slug)').eq('user_id',user.id).limit(200);if(joined.error)throw joined.error;
    const select=root.querySelector('[name="community_id"]');(joined.data||[]).forEach(row=>{if(row.communities)select.insertAdjacentHTML('beforeend',`<option value="${row.communities.id}">${escapeHTML(row.communities.name)}</option>`)});
    const memberIds=(joined.data||[]).map(row=>row.community_id),connectionRows=await supabase.from('connections').select('user_low,user_high').or(`user_low.eq.${user.id},user_high.eq.${user.id}`);if(connectionRows.error)throw connectionRows.error;
    const connectionIds=connectionRows.data.map(row=>row.user_low===user.id?row.user_high:row.user_low);
    root.querySelector('#post-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,fd=new FormData(form),body=fd.get('body').toString().trim(),community_id=fd.get('community_id');const {error:saveError}=await supabase.from('posts').insert({author_id:user.id,community_id,body});if(saveError)commonFormMessage(root.querySelector('#post-feedback'),saveError.message,'error');else{commonFormMessage(root.querySelector('#post-feedback'),'Your post is live in the selected community.');form.reset();await loadPosts(root.querySelector('#feed-list'),null,memberIds,connectionIds)}});
    if(memberIds.length||connectionIds.length)await loadPosts(root.querySelector('#feed-list'),null,memberIds,connectionIds);else root.querySelector('#feed-list').innerHTML=state('Join a community or connect with players','Posts from your communities and connections will appear here.','<a class="btn" href="/pages/communities.html">Browse communities</a> <a class="btn" href="/pages/explore.html">Find players</a>');
  }
 },{backend:false});
}
function explore(){entry('explore',async({root,configured})=>{
 root.insertAdjacentHTML('beforeend',`<form class="toolbar" id="explore-form"><input class="field" name="q" placeholder="Search players, creators, communities, games" value="${escapeHTML(new URLSearchParams(location.search).get('q')||'')}"><button class="btn btn-primary">Search</button></form><div id="explore-results"></div>`);
 const form=root.querySelector('#explore-form'),result=root.querySelector('#explore-results');
 async function search(){
  const term=new FormData(form).get('q').toString().trim();
  if(!term){result.innerHTML=state('Search GameVault','Enter a game, creator, player, or community. Results come from Supabase after it is configured.');return}
  if(!configured){result.innerHTML=state('Backend not configured','Search results require the GameVault Supabase project. The game catalog preview is available on the Games page.','<a class="btn" href="/games/index.html">Browse game catalog</a>');return}
  result.innerHTML='<div class="state loading">Searching connected directories…</div>';
  try{
   const data=await searchDirectory(term);
   const cards=[...data.profiles.map(profile=>playerRow(profile,profile.bio||'Public GameVault profile')),
    ...data.communities.map(c=>cardLink(c.name,`/pages/community.html?slug=${encodeURIComponent(c.slug)}`,c.description||'Public community','◉',`${c.member_count||0} members`)),
    ...data.games.map(g=>cardLink(g.title,`/games/${encodeURIComponent(g.slug)}/`,g.genre||'Game catalog listing','▣'))];
   result.innerHTML=cards.length?`<div class="data-list">${cards.join('')}</div>`:state('No matches','No public profiles, communities, or games matched that search.')
  }catch(err){result.innerHTML=error(err.message)}
 }
 form.addEventListener('submit',e=>{e.preventDefault();const term=new FormData(form).get('q').toString();history.replaceState(null,'',`?q=${encodeURIComponent(term)}`);search()});
 if(new URLSearchParams(location.search).has('q'))search();else result.innerHTML=state('Explore GameVault','Search for a name or game. We only show public profiles and communities allowed by their privacy settings.');
});}

function communities(){entry('communities',async({root,configured})=>{
 root.insertAdjacentHTML('beforeend',`<section class="surface surface-pad" id="community-create-area"></section><div class="toolbar" style="margin-top:18px"><input class="field" id="community-search" placeholder="Search public communities"><select class="select" id="community-game"><option value="">All games</option>${catalog.map(g=>`<option value="${g.slug}">${escapeHTML(g.title)}</option>`).join('')}</select><button class="btn" id="community-find">Filter</button></div><div id="community-list"></div>`);
 const list=root.querySelector('#community-list'),create=root.querySelector('#community-create-area');
 if(!configured){create.innerHTML=`<h2 class="section-title">Create a community</h2><p class="muted tiny">Supabase is required to create or join real communities.</p><a class="btn" href="/pages/signup.html">Create account</a>`;list.innerHTML=state('Community directory is empty until connected','No community samples are shown. Connect Supabase to browse and join real GameVault communities.');return}
 const {data:{user}}=await getOptionalUser();
 const dbGames=await supabase.from('games').select('id,slug,title').order('title').limit(400);if(dbGames.error)throw dbGames.error;
 if(user){create.innerHTML=`<h2 class="section-title">Create a community</h2><form id="community-create-form" class="form-stack"><label class="field-wrap">Community name<input class="field" name="name" maxlength="80" required></label><label class="field-wrap">Description<textarea class="textarea" name="description" maxlength="2000"></textarea></label><label class="field-wrap">Choose a Grand Theft Auto title<select class="select" name="game_id" required>${dbGames.data.map(g=>`<option value="${g.id}">${escapeHTML(g.title)}</option>`).join('')}</select></label><label class="field-wrap">Rules (one per line)<textarea class="textarea" name="rules" maxlength="2000" placeholder="Respect other players"></textarea></label><label class="field-wrap">Listing<select class="select" name="visibility"><option value="public">Public</option><option value="private">Private — invitation link only</option></select></label><label class="field-wrap">Membership access<select class="select" name="membership_mode"><option value="open">Open — anyone can join</option><option value="approval">Approval — a community steward reviews requests</option><option value="invite_only">Invite only</option></select></label><div id="community-create-feedback"></div><button class="btn btn-primary">Create community</button></form>`;create.querySelector('#community-create-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),name=fd.get('name').toString().trim(),slug=name.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,65)+'-'+crypto.randomUUID().slice(0,6),rules=fd.get('rules').toString().split('\n').map(x=>x.trim()).filter(Boolean).slice(0,20);const {data:created,error:createError}=await supabase.from('communities').insert({slug,name,owner_id:user.id,description:fd.get('description').toString().trim(),game_id:fd.get('game_id')||null,rules,visibility:fd.get('visibility'),membership_mode:fd.get('membership_mode')}).select('slug').single();if(createError){commonFormMessage(root.querySelector('#community-create-feedback'),createError.message,'error');return}location.href='/pages/community.html?slug='+encodeURIComponent(created.slug)})}else create.innerHTML=`<h2 class="section-title">Create a community</h2><p class="muted tiny">Sign in to create a real GameVault community.</p>${authPrompt()}`;
  async function load(){
    list.innerHTML='<div class="state loading">Loading public communities…</div>';
    let q=supabase.from('communities').select('id,slug,name,description,visibility,membership_mode,game_id,member_count,games(title,slug)').eq('visibility','public').order('name').limit(100);
    const term=root.querySelector('#community-search').value.trim();if(term)q=q.ilike('name',`%${term.replace(/[%_,]/g,'')}%`);
    const {data,error:loadError}=await q;if(loadError){list.innerHTML=error(loadError.message);return}
    const gameSlug=root.querySelector('#community-game').value,filtered=(data||[]).filter(c=>!gameSlug||catalog.find(g=>g.slug===gameSlug)?.title===c.games?.title);
    let joined=new Set(),pending=new Set();
    if(user&&filtered.length){const ids=filtered.map(c=>c.id),membership=await supabase.from('community_members').select('community_id').eq('user_id',user.id).in('community_id',ids);if(membership.error){list.innerHTML=error(membership.error.message);return}joined=new Set(membership.data.map(x=>x.community_id));const requests=await supabase.from('community_join_requests').select('community_id').eq('requester_id',user.id).eq('status','pending').in('community_id',ids);if(requests.error){list.innerHTML=error(requests.error.message);return}pending=new Set(requests.data.map(x=>x.community_id))}
    list.innerHTML=filtered.length?`<div class="grid grid-3">${filtered.map(c=>{const joinedHere=joined.has(c.id),pendingHere=pending.has(c.id),mode=c.membership_mode||'open';const action=!user?`<a class="btn btn-primary" href="/pages/login.html">Sign in to join</a>`:joinedHere?'<button class="btn" disabled>Joined ✓</button>':mode==='open'?`<button class="btn btn-primary directory-join" data-id="${c.id}" data-mode="open">Join</button>`:mode==='approval'?`<button class="btn directory-join" data-id="${c.id}" data-mode="approval" ${pendingHere?'disabled':''}>${pendingHere?'Request pending':'Request to join'}</button>`:'<span class="pill">Invite only</span>';const modeLabel=mode==='approval'?'Approval required':mode==='invite_only'?'Invite only':'Open membership';const art=gameArt(c.games?.slug);return `<article class="surface surface-pad">${art?`<div class="gv-community-art" style="background-image:linear-gradient(90deg,#0c1218bb,#0c121899),url('${escapeHTML(art)}')"></div>`:''}<p class="eyebrow">${escapeHTML(c.games?.title||'Community')}</p><h2 class="section-title">${escapeHTML(c.name)}</h2><p class="muted tiny">${escapeHTML(c.description||'No description provided.')}</p><p class="muted tiny">${Number(c.member_count)||0} members · ${modeLabel}</p><div class="row"><a class="btn" href="/pages/community.html?slug=${encodeURIComponent(c.slug)}">Details →</a>${action}</div></article>`}).join('')}</div>`:state('No public communities yet','Try another filter, or create a community after signing in.');
    list.querySelectorAll('.directory-join').forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;const result=button.dataset.mode==='approval'?await supabase.from('community_join_requests').insert({community_id:button.dataset.id,requester_id:user.id}):await supabase.from('community_members').insert({community_id:button.dataset.id,user_id:user.id,role:'member'});if(result.error){button.disabled=false;button.textContent='Could not join — retry';button.title=result.error.message}else await load()}));
  }
 root.querySelector('#community-find').addEventListener('click',load);root.querySelector('#community-search').addEventListener('keydown',e=>{if(e.key==='Enter')load()});root.querySelector('#community-game').addEventListener('change',load);await load();
});}
function community(){entry('community',async({root,configured})=>{
 const slug=new URLSearchParams(location.search).get('slug');
 if(!slug){root.insertAdjacentHTML('beforeend',state('Choose a community','Open any community from the directory to see its details.','<a class="btn" href="/pages/communities.html">Browse communities</a>'));return}
 if(!configured){root.insertAdjacentHTML('beforeend',state('Community data is not connected','Connect Supabase to load real community descriptions, rules, members, posts, and membership actions.'));return}
 const {data:c,error:loadError}=await supabase.from('communities').select('id,slug,name,description,rules,visibility,membership_mode,game_id,owner_id,member_count,games(title,slug)').eq('slug',slug).maybeSingle();if(loadError)throw loadError;
 if(!c){showBackendEmpty(root,'Community not found or not visible','The community may be private, unavailable, or the link may be incorrect.','<a class="btn" href="/pages/communities.html">Back to communities</a>');return}
 const {data:{user}}=await getOptionalUser();const membership=user?await supabase.from('community_members').select('role').eq('community_id',c.id).eq('user_id',user.id).maybeSingle():{data:null,error:null};if(membership.error)throw membership.error;const role=membership.data?.role,joined=Boolean(role),isOwner=c.owner_id===user?.id,mode=c.membership_mode||'open';
 let siteModerator=false;if(user){const roleResult=await supabase.from('user_roles').select('role').eq('user_id',user.id).in('role',['moderator','admin']).limit(1);if(roleResult.error)throw roleResult.error;siteModerator=Boolean(roleResult.data?.length)}const canManage=Boolean(user&&(isOwner||siteModerator||['owner','moderator'].includes(role))),canInvite=canManage;
 let joinRequest=null;if(user&&!joined&&mode==='approval'){const request=await supabase.from('community_join_requests').select('id').eq('community_id',c.id).eq('requester_id',user.id).eq('status','pending').maybeSingle();if(request.error)throw request.error;joinRequest=request.data}
 const membershipAction=!user?authPrompt():joined?isOwner?'<span class="pill">Community owner</span>':'<button id="membership-action" data-action="leave" class="btn btn-primary">Leave community</button>':c.visibility!=='public'?'<a class="btn btn-primary" href="/pages/notifications.html">Review invitation</a>':mode==='open'?'<button id="membership-action" data-action="join" class="btn btn-primary">Join community</button>':mode==='approval'?joinRequest?'<button class="btn" disabled>Request pending</button>':'<button id="membership-action" data-action="request" class="btn btn-primary">Request to join</button>':'<span class="pill">Invite only</span>';
 root.insertAdjacentHTML('beforeend',`<section class="feature-hero" style="background-image:linear-gradient(90deg,#090910ed,#09091066),url('/assets/supplied/community-bg.jpg')"><div><span class="pill">${escapeHTML(c.games?.title||'Community')}</span><h2>${escapeHTML(c.name)}</h2><p>${escapeHTML(c.description||'Community members have not added a description yet.')}</p><div class="row"><span class="muted tiny">${Number(c.member_count)||0} members</span><span class="pill">${escapeHTML(c.visibility)} · ${escapeHTML(mode.replace('_',' '))}</span>${membershipAction}</div></div></section><div class="grid grid-2"><section class="surface surface-pad"><h2 class="section-title">Community rules</h2>${(c.rules||[]).length?`<ol class="muted tiny">${c.rules.map(r=>`<li>${escapeHTML(r)}</li>`).join('')}</ol>`:state('No rules published','This community has not added any rules yet.')}</section><section class="surface surface-pad"><h2 class="section-title">Members</h2><div id="community-members"></div></section></div>${canInvite?`<section class="surface surface-pad" style="margin-top:16px"><h2 class="section-title">Invite a public player</h2><form id="invite-form" class="toolbar"><input class="field" name="username" required placeholder="GameVault username"><button class="btn">Send invitation</button></form><div id="invite-feedback"></div></section>`:''}<h2 class="section-title" style="margin-top:24px">Community posts</h2><div class="grid" id="community-posts"></div><div id="community-report" style="margin-top:16px"><button class="btn" id="report-community">Report this community</button></div>`);
 const bannerArt=gameArt(c.games?.slug);if(bannerArt)root.querySelector('.feature-hero').style.backgroundImage=`linear-gradient(90deg,#090910ed,#09091066),url('${bannerArt}')`;
 root.querySelector('#membership-action')?.addEventListener('click',async e=>{const button=e.currentTarget;button.disabled=true;let outcome;if(button.dataset.action==='leave')outcome=await supabase.from('community_members').delete().eq('community_id',c.id).eq('user_id',user.id);else if(button.dataset.action==='request')outcome=await supabase.from('community_join_requests').insert({community_id:c.id,requester_id:user.id});else outcome=await supabase.from('community_members').insert({community_id:c.id,user_id:user.id,role:'member'});if(outcome.error){button.disabled=false;button.title=outcome.error.message;button.textContent='Could not update — retry'}else location.reload()});
 if(canManage){const games=await supabase.from('games').select('id,title').order('title').limit(300);if(games.error)throw games.error;root.querySelector('#community-report').insertAdjacentHTML('beforebegin',`<section id="community-settings" class="surface surface-pad" style="margin:18px 0"><h2 class="section-title">Community settings</h2><form id="community-settings-form" class="form-stack"><label class="field-wrap">Name<input class="field" name="name" maxlength="80" value="${escapeHTML(c.name)}" required></label><label class="field-wrap">Description<textarea class="textarea" name="description" maxlength="2000">${escapeHTML(c.description||'')}</textarea></label><label class="field-wrap">Game or topic<select class="select" name="game_id" required>${games.data.map(g=>`<option value="${g.id}" ${c.game_id===g.id?'selected':''}>${escapeHTML(g.title)}</option>`).join('')}</select></label><label class="field-wrap">Rules, one per line<textarea class="textarea" name="rules" maxlength="2000">${escapeHTML((c.rules||[]).join('\n'))}</textarea></label><label class="field-wrap">Listing<select class="select" name="visibility"><option value="public" ${c.visibility==='public'?'selected':''}>Public</option><option value="private" ${c.visibility==='private'?'selected':''}>Private — invitation link only</option></select></label><label class="field-wrap">Membership access<select class="select" name="membership_mode"><option value="open" ${mode==='open'?'selected':''}>Open</option><option value="approval" ${mode==='approval'?'selected':''}>Approval required</option><option value="invite_only" ${mode==='invite_only'?'selected':''}>Invite only</option></select></label><div id="community-settings-feedback"></div><button class="btn btn-primary">Save community settings</button></form></section><section class="surface surface-pad" id="community-join-requests"><h2 class="section-title">Join requests</h2><div id="join-request-list"><div class="state loading">Loading requests…</div></div></section>`);
  const requests=await supabase.from('community_join_requests').select('id,requester_id,created_at').eq('community_id',c.id).eq('status','pending').order('created_at',{ascending:true}).limit(50);if(requests.error)root.querySelector('#join-request-list').innerHTML=error(requests.error.message);else if(!requests.data.length)root.querySelector('#join-request-list').innerHTML=state('No pending requests','Requests to join this community will appear here.');else{const people=await supabase.from('profile_cards').select('id,username,display_name,avatar_url').in('id',requests.data.map(x=>x.requester_id));if(people.error)root.querySelector('#join-request-list').innerHTML=error(people.error.message);else{const byId=new Map(people.data.map(x=>[x.id,x]));root.querySelector('#join-request-list').innerHTML=`<div class="data-list">${requests.data.map(r=>{const p=byId.get(r.requester_id);return `<article class="data-row">${avatarMarkup(p||{id:r.requester_id},'gv-player-avatar','Player avatar')}<span class="grow"><strong>${escapeHTML(p?.display_name||p?.username||'GameVault player')}</strong><p>Requested ${date(r.created_at)}</p></span><button class="btn join-request-action" data-id="${r.id}" data-approve="false">Decline</button><button class="btn btn-primary join-request-action" data-id="${r.id}" data-approve="true">Approve</button></article>`}).join('')}</div>`;root.querySelectorAll('.join-request-action').forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;const {error:responseError}=await supabase.rpc('respond_to_community_join_request',{request_id:button.dataset.id,approve_join:button.dataset.approve==='true'});if(responseError){button.disabled=false;alert(responseError.message)}else location.reload()}))}}
  root.querySelector('#community-settings-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),rules=fd.get('rules').toString().split('\n').map(x=>x.trim()).filter(Boolean).slice(0,20);const {error:updateError}=await supabase.from('communities').update({name:fd.get('name').toString().trim(),description:fd.get('description').toString().trim(),game_id:fd.get('game_id')||null,rules,visibility:fd.get('visibility'),membership_mode:fd.get('membership_mode')}).eq('id',c.id);commonFormMessage(root.querySelector('#community-settings-feedback'),updateError?.message||'Community settings saved.',updateError?'error':'success');if(!updateError)setTimeout(()=>location.reload(),700)});
 }
  const members=await supabase.from('community_members').select('user_id,role').eq('community_id',c.id).limit(40);if(members.error)root.querySelector('#community-members').innerHTML=error(members.error.message);else{const ids=(members.data||[]).map(m=>m.user_id),visible=ids.length?await supabase.from('profile_cards').select('id,username,display_name,avatar_url').in('id',ids):{data:[],error:null};if(visible.error)root.querySelector('#community-members').innerHTML=error(visible.error.message);else{const byId=new Map((visible.data||[]).map(p=>[p.id,p]));root.querySelector('#community-members').innerHTML=(members.data||[]).length?`<div class="data-list">${members.data.map(m=>{const p=byId.get(m.user_id),label=m.role==='owner'?'Community owner':m.role==='moderator'?'Community moderator':'Community member';return p?playerRow(p,label):infoRow('Private member',label,'◎')}).join('')}</div>`:state('No visible members','Member details are private or the community has no members listed.')}}
 if(canInvite)root.querySelector('#invite-form').addEventListener('submit',async e=>{e.preventDefault();const feedback=root.querySelector('#invite-feedback'),username=new FormData(e.currentTarget).get('username').toString().trim().replace(/^@/,'');const target=await supabase.from('profile_cards').select('id,username').eq('username',username).maybeSingle();if(target.error){commonFormMessage(feedback,target.error.message,'error');return}if(!target.data){commonFormMessage(feedback,'No public profile found for that username.','error');return}const {error:inviteError}=await supabase.from('community_invitations').insert({community_id:c.id,inviter_id:user.id,invitee_id:target.data.id});if(inviteError)commonFormMessage(feedback,inviteError.message,'error');else{commonFormMessage(feedback,'Invitation sent.');e.currentTarget.reset()}});
 await loadPosts(root.querySelector('#community-posts'),c.id);
 root.querySelector('#report-community')?.addEventListener('click',async()=>{if(!user){location.href='/pages/login.html';return}const reason=prompt('Briefly describe the community rule concern:');if(!reason?.trim())return;const {error:reportError}=await supabase.from('moderation_reports').insert({reporter_id:user.id,subject_type:'community',subject_id:c.id,reason:reason.trim()});if(reportError)alert('Report could not be sent: '+reportError.message);else alert('Report sent to GameVault moderation.')});
});}
function profile(){
 entry('profile',async({root,configured})=>{
  const username=new URLSearchParams(location.search).get('username');
  if(!username){root.insertAdjacentHTML('beforeend',state('Profile link needs a username','Open a player profile from Explore or a community page.'));return}
  if(!configured){root.insertAdjacentHTML('beforeend',state('Profile data is not connected','Connect Supabase to read public player profiles. Private fields are excluded by database policies.'));return}
  const {data:p,error:loadError}=await supabase.from('profile_cards').select('id,username,display_name,avatar_url,bio,social_links,show_socials,show_games,show_platforms,show_connections,created_at').eq('username',username).maybeSingle();
  if(loadError)throw loadError;
  if(!p){showBackendEmpty(root,'Profile is private or unavailable','The player has not shared a public profile, or the username does not exist.');return}
  const displayName=p.display_name||p.username;
  const img=avatarMarkup(p,'profile-cover-avatar',`${displayName} avatar`);
  root.insertAdjacentHTML('beforeend',`<section class="profile-cover"><div class="profile-cover-content">${img}<div class="profile-cover-details"><h2>${escapeHTML(displayName)}</h2><p>@${escapeHTML(p.username)} · GameVault member since ${date(p.created_at)}</p>${p.bio?`<p class="profile-bio">${escapeHTML(p.bio)}</p>`:''}<div class="profile-cover-actions" id="profile-social-actions">${p.show_socials?renderSocialMenu(p.social_links):''}<button class="btn btn-danger" id="report-profile">Report profile</button></div></div></div></section><section class="profile-metrics" aria-label="Public profile details"><div class="profile-metric"><strong id="metric-games">${p.show_games?'…':'Private'}</strong><span>Games shared</span></div><div class="profile-metric"><strong id="metric-platforms">${p.show_platforms?'…':'Private'}</strong><span>Platforms</span></div><div class="profile-metric"><strong id="metric-achievements">…</strong><span>Achievements</span></div><div class="profile-metric"><strong id="metric-connections">${p.show_connections?'…':'Private'}</strong><span>Connections</span></div></section><div class="profile-layout"><div class="profile-main-column"><section class="surface profile-detail-card"><h3>Game library</h3><div id="profile-games"><div class="state loading">Loading shared games…</div></div></section><section class="surface profile-detail-card"><h3>Achievements</h3><div id="profile-achievements"><div class="state loading">Loading achievements…</div></div></section></div><aside class="profile-side-column"><section class="surface profile-detail-card"><h3>Platforms</h3><div id="profile-platforms"><div class="state loading">Loading platforms…</div></div></section><section class="surface profile-detail-card"><h3>Connections</h3><div id="profile-connections"><div class="state loading">Loading connections…</div></div></section></aside></div>`);
  if(p.show_games){const games=await supabase.from('public_profile_games').select('slug,title,genre,is_favorite,is_currently_playing').eq('user_id',p.id).limit(30);if(games.error)root.querySelector('#profile-games').innerHTML=error(games.error.message);else{root.querySelector('#metric-games').textContent=String(games.data?.length||0);root.querySelector('#profile-games').innerHTML=games.data?.length?`<div class="data-list">${games.data.map(g=>cardLink(g.title,`/games/${encodeURIComponent(g.slug)}/`,g.genre||'Game',g.is_favorite?'★':'▣',g.is_currently_playing?'Playing':'')).join('')}</div>`:state('No public games','This player has not shared games.')}}
  else root.querySelector('#profile-games').innerHTML=state('Games hidden','This player has chosen not to show their game library.');
  if(p.show_platforms){const platforms=await supabase.from('public_profile_platforms').select('name').eq('user_id',p.id).order('name');if(platforms.error)root.querySelector('#profile-platforms').innerHTML=error(platforms.error.message);else{root.querySelector('#metric-platforms').textContent=String(platforms.data?.length||0);root.querySelector('#profile-platforms').innerHTML=platforms.data?.length?`<div class="row">${platforms.data.map(x=>`<span class="pill">${escapeHTML(x.name)}</span>`).join('')}</div>`:state('No public platforms','This player has not shared platform selections.')}}
  else root.querySelector('#profile-platforms').innerHTML=state('Platforms hidden','This player has chosen not to show platforms.');
  const achievements=await supabase.from('public_profile_achievements').select('title,description,awarded_at').eq('user_id',p.id).limit(20);if(achievements.error)root.querySelector('#profile-achievements').innerHTML=error(achievements.error.message);else{root.querySelector('#metric-achievements').textContent=String(achievements.data?.length||0);root.querySelector('#profile-achievements').innerHTML=achievements.data?.length?`<div class="data-list">${achievements.data.map(a=>infoRow(a.title,a.description||'Achievement','✦',date(a.awarded_at))).join('')}</div>`:state('No public achievements','No achievements have been shared.')}
  if(p.show_connections){const connections=await supabase.from('public_profile_connections').select('connected_user_id,username,display_name').eq('user_id',p.id).limit(30);if(connections.error)root.querySelector('#profile-connections').innerHTML=error(connections.error.message);else{root.querySelector('#metric-connections').textContent=String(connections.data?.length||0);root.querySelector('#profile-connections').innerHTML=connections.data?.length?`<div class="data-list">${connections.data.map(c=>cardLink(c.display_name||c.username,`/pages/profile.html?username=${encodeURIComponent(c.username)}`,'GameVault connection','◎')).join('')}</div>`:state('No public connections','No connections have been shared.')}}
  else root.querySelector('#profile-connections').innerHTML=state('Connections hidden','This player has chosen not to display their connections.');
  const {data:{user:viewer},error:viewerError}=await getOptionalUser();if(viewerError)throw viewerError;
  if(viewer?.id===p.id)root.querySelector('#profile-social-actions').insertAdjacentHTML('afterbegin','<a class="btn btn-primary" href="/pages/account/profile.html">Edit profile</a>');
  if(viewer&&viewer.id!==p.id){
   const [outgoing,incoming,connectionRows,muteRow]=await Promise.all([supabase.from('connection_requests').select('id,status').eq('sender_id',viewer.id).eq('recipient_id',p.id).order('created_at',{ascending:false}).limit(1),supabase.from('connection_requests').select('id,status').eq('sender_id',p.id).eq('recipient_id',viewer.id).order('created_at',{ascending:false}).limit(1),supabase.from('connections').select('user_low,user_high').or(`user_low.eq.${viewer.id},user_high.eq.${viewer.id}`),supabase.from('user_mutes').select('muted_id').eq('muter_id',viewer.id).eq('muted_id',p.id).maybeSingle()]);for(const result of [outgoing,incoming,connectionRows,muteRow])if(result.error)throw result.error;
   const isConnected=connectionRows.data.some(c=>(c.user_low===viewer.id?c.user_high:c.user_low)===p.id),sent=outgoing.data?.find(r=>r.status==='pending'),received=incoming.data?.find(r=>r.status==='pending'),isMuted=Boolean(muteRow.data),actions=root.querySelector('#profile-social-actions');
   actions.insertAdjacentHTML('afterbegin',`${isConnected?'<span class="pill">Connected</span>':sent?'<span class="pill">Request pending</span>':received?`<button class="btn btn-primary connection-response" data-id="${received.id}" data-accept="true">Accept request</button><button class="btn connection-response" data-id="${received.id}" data-accept="false">Decline</button>`:'<button class="btn btn-primary" id="connect-player">Connect</button>'}<a class="btn" href="/pages/messages.html?username=${encodeURIComponent(p.username)}">Message</a><button class="btn" id="mute-player">${isMuted?'Unmute':'Mute'}</button><button class="btn btn-danger" id="block-player">Block</button><span id="relationship-feedback"></span>`);
   root.querySelector('#connect-player')?.addEventListener('click',async e=>{const button=e.currentTarget;button.disabled=true;const {error:requestError}=await supabase.rpc('send_connection_request',{target_user:p.id});if(requestError){button.disabled=false;commonFormMessage(root.querySelector('#relationship-feedback'),requestError.message,'error')}else{button.textContent='Request pending';commonFormMessage(root.querySelector('#relationship-feedback'),'Request sent. Only the recipient can accept or decline it.')}});
   root.querySelectorAll('.connection-response').forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;const {error:responseError}=await supabase.rpc('respond_to_connection_request',{request_id:button.dataset.id,accept_request:button.dataset.accept==='true'});if(responseError){button.disabled=false;commonFormMessage(root.querySelector('#relationship-feedback'),responseError.message,'error')}else location.reload()}));
   root.querySelector('#mute-player')?.addEventListener('click',async()=>{const response=isMuted?await supabase.from('user_mutes').delete().eq('muter_id',viewer.id).eq('muted_id',p.id):await supabase.from('user_mutes').insert({muter_id:viewer.id,muted_id:p.id});if(response.error)commonFormMessage(root.querySelector('#relationship-feedback'),response.error.message,'error');else location.reload()});
   root.querySelector('#block-player')?.addEventListener('click',async()=>{if(!confirm(`Block @${p.username}? Their public profile and posts will be hidden from you.`))return;const {error:blockError}=await supabase.from('user_blocks').insert({blocker_id:viewer.id,blocked_id:p.id});if(blockError)commonFormMessage(root.querySelector('#relationship-feedback'),blockError.message,'error');else location.href='/pages/account/privacy.html'});
  }
  root.querySelector('#report-profile')?.addEventListener('click',async()=>{const {data:{user}}=await getOptionalUser();if(!user){location.href='/pages/login.html';return}const reason=prompt('Briefly describe the profile concern:');if(!reason?.trim())return;const {error:e}=await supabase.from('moderation_reports').insert({reporter_id:user.id,subject_type:'profile',subject_id:p.id,reason:reason.trim()});alert(e?'Report could not be sent: '+e.message:'Report sent to GameVault moderation.')});
 });
}
function creators(){entry('creators',async({root,configured})=>{
 if(!configured){root.insertAdjacentHTML('beforeend',state('Creator hub is waiting for connected accounts','Real creator profiles and featured work appear here after Supabase is configured.'));return}
 const {data:{user}}=await getOptionalUser();
 if(user){const own=await supabase.from('creator_profiles').select('headline,featured_work_title,featured_work_url,is_public').eq('user_id',user.id).maybeSingle();if(own.error)throw own.error;root.insertAdjacentHTML('beforeend',`<section class="surface surface-pad" style="margin-bottom:20px"><h2 class="section-title">Your creator profile</h2><form id="creator-form" class="form-stack"><label class="field-wrap">Creator headline<input class="field" name="headline" maxlength="180" value="${escapeHTML(own.data?.headline||'')}" placeholder="What do you make?"></label><label class="field-wrap">Featured work title<input class="field" name="featured_work_title" maxlength="120" value="${escapeHTML(own.data?.featured_work_title||'')}"></label><label class="field-wrap">Featured work URL<input class="field" name="featured_work_url" type="url" value="${escapeHTML(own.data?.featured_work_url||'')}" placeholder="https://…"></label><label class="check-line"><input type="checkbox" name="is_public" ${own.data?.is_public?'checked':''}>Publish my creator card publicly</label><div id="creator-feedback"></div><button class="btn btn-primary">Save creator profile</button></form></section>`);root.querySelector('#creator-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),url=fd.get('featured_work_url').toString().trim();if(url&&!safeExternalHref(url)){commonFormMessage(root.querySelector('#creator-feedback'),'Featured work URL must use HTTPS.','error');return}const {error:saveError}=await supabase.from('creator_profiles').upsert({user_id:user.id,headline:fd.get('headline').toString().trim(),featured_work_title:fd.get('featured_work_title').toString().trim(),featured_work_url:url||null,is_public:fd.has('is_public')},{onConflict:'user_id'});if(saveError)commonFormMessage(root.querySelector('#creator-feedback'),saveError.message,'error');else{commonFormMessage(root.querySelector('#creator-feedback'),'Creator profile saved.');setTimeout(()=>location.reload(),700)}})}else root.insertAdjacentHTML('beforeend',`<section class="surface surface-pad" style="margin-bottom:20px"><h2 class="section-title">Publish your work</h2><p class="muted tiny">Sign in to create a public creator card. Your profile privacy still applies.</p>${authPrompt()}</section>`);
 const {data,error:loadError}=await supabase.from('creator_profiles').select('user_id,headline,featured_work_url,featured_work_title').eq('is_public',true).order('created_at',{ascending:false}).limit(40);if(loadError)throw loadError;
 if(!data?.length){root.insertAdjacentHTML('beforeend',state('No public creators yet','Creator profiles will appear here after members choose to publish them.'));return}
 const ids=data.map(c=>c.user_id),cards=await supabase.from('profile_cards').select('id,username,display_name,avatar_url').in('id',ids);if(cards.error)throw cards.error;const byId=new Map((cards.data||[]).map(c=>[c.id,c]));
 root.insertAdjacentHTML('beforeend',`<div class="grid grid-3">${data.map(c=>{const profile=byId.get(c.user_id),href=safeExternalHref(c.featured_work_url);return `<article class="surface surface-pad"><div class="row">${avatarMarkup(profile||{id:c.user_id},'gv-player-avatar','Creator avatar')}<p class="eyebrow">GameVault creator</p></div><h2 class="section-title">${escapeHTML(profile?.display_name||profile?.username||'Private creator')}</h2><p class="muted tiny">${escapeHTML(c.headline||'')}</p>${href?`<a class="btn" href="${escapeHTML(href)}" target="_blank" rel="noopener noreferrer">${escapeHTML(c.featured_work_title||'Featured work')} ↗</a>`:''}<div class="divider"></div>${profile?`<a class="btn" href="/pages/profile.html?username=${encodeURIComponent(profile.username)}">View creator profile</a>`:'<span class="muted tiny">Profile is private</span>'}</article>`}).join('')}</div>`)
});}
function media(){entry('media',async({root,configured})=>{root.insertAdjacentHTML('beforeend',`<div class="toolbar"><input class="field" id="asset-search" placeholder="Search all supplied images"><select class="select" id="asset-category"><option value="">All image types</option>${[...new Set(suppliedImages.map(x=>x.category))].map(c=>`<option>${escapeHTML(c)}</option>`).join('')}</select></div><section class="surface surface-pad" style="margin-bottom:18px"><h2 class="section-title">Submit your own media</h2><p class="muted tiny">Images or video up to 50 MB are stored in Supabase and held for moderation. Uploaded files are never represented as published before approval.</p><form class="toolbar" id="upload-form"><input type="file" id="media-file" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm" class="field"><input class="field" id="media-caption" maxlength="180" placeholder="Caption (optional)"><button class="btn btn-primary">Upload for review</button></form><div id="upload-feedback"></div></section><h2 class="section-title">Supplied image library · ${suppliedImages.length} files</h2><p class="muted tiny">Every image from the provided folder is linked below with its intended role. Portraits are selectable avatar assets, not fake member accounts; lifestyle, flag, UI, and external-logo images retain their actual category.</p><div class="grid grid-4" id="asset-grid">${suppliedImages.map(galleryCard).join('')}</div>`);
  const grid=root.querySelector('#asset-grid');function filter(){const q=root.querySelector('#asset-search').value.toLowerCase(),c=root.querySelector('#asset-category').value;const list=suppliedImages.filter(i=>(!q||`${i.path} ${i.category} ${i.purpose}`.toLowerCase().includes(q))&&(!c||i.category===c));grid.innerHTML=list.length?list.map(galleryCard).join(''):state('No images match','Try another filename or category.')}root.querySelector('#asset-search').addEventListener('input',filter);root.querySelector('#asset-category').addEventListener('change',filter);
  if(configured){const mediaSection=document.createElement('section');mediaSection.innerHTML='<h2 class="section-title" style="margin-top:24px">Approved member media</h2><div class="grid grid-3" id="approved-media"><div class="state loading">Loading approved media…</div></div>';root.insertBefore(mediaSection,root.querySelector('h2.section-title'));const media=await supabase.from('media_items').select('id,owner_id,game_id,storage_path,media_type,caption,created_at,games(title)').eq('review_state','approved').eq('visibility','public').order('created_at',{ascending:false}).limit(36);const target=mediaSection.querySelector('#approved-media');if(media.error)target.innerHTML=error(media.error.message);else if(!media.data?.length)target.innerHTML=state('No approved member uploads yet','Media appears here after a moderator approves a real member upload.');else{const cards=await Promise.all(media.data.map(async item=>{const signed=await supabase.storage.from('vexra-media').createSignedUrl(item.storage_path,3600);if(signed.error)return `<article class="surface surface-pad"><span class="pill">Approved member upload</span><h3 class="section-title">${escapeHTML(item.caption||item.games?.title||'Community media')}</h3><p class="muted tiny">This file could not be opened right now.</p></article>`;const url=escapeHTML(signed.data.signedUrl),element=item.media_type==='video'?`<video controls preload="none" src="${url}" style="width:100%;height:100%;object-fit:cover"></video>`:`<img loading="lazy" src="${url}" alt="${escapeHTML(item.caption||'Member media')}" style="width:100%;height:100%;object-fit:cover">`;return `<article class="surface asset-card"><a class="asset-thumb" href="${url}" target="_blank" rel="noopener">${element}</a><div class="asset-meta"><strong>${escapeHTML(item.caption||item.games?.title||'Member media')}</strong><span>Approved member upload${item.games?.title?' · '+escapeHTML(item.games.title):''} · ${date(item.created_at)}</span></div></article>`}));target.innerHTML=cards.join('')}}
  root.querySelector('#upload-form').addEventListener('submit',async e=>{e.preventDefault();const feedback=root.querySelector('#upload-feedback');const file=root.querySelector('#media-file').files[0];if(!allowedFile(file,true)){commonFormMessage(feedback,'Choose a JPG, PNG, WebP, GIF, MP4, or WebM file smaller than 50 MB.','error');return}if(!configured){commonFormMessage(feedback,'Backend not configured. The file was not uploaded.','error');return}const {data:{user}}=await getOptionalUser();if(!user){location.href='/pages/login.html';return}const path=`${user.id}/${crypto.randomUUID()}-${file.name.replace(/[^a-z0-9._-]/gi,'_')}`;const {error:uploadError}=await supabase.storage.from('vexra-media').upload(path,file,{contentType:file.type,upsert:false});if(uploadError){commonFormMessage(feedback,uploadError.message,'error');return}const caption=root.querySelector('#media-caption').value.trim();const {error:rowError}=await supabase.from('media_items').insert({owner_id:user.id,storage_path:path,media_type:file.type.startsWith('video/')?'video':'image',caption,review_state:'pending'});if(rowError){const cleanup=await supabase.storage.from('vexra-media').remove([path]);commonFormMessage(feedback,cleanup.error?`Review record failed and the uploaded file needs cleanup: ${rowError.message}`:`Upload could not be registered and the file was removed: ${rowError.message}`,'error');return}commonFormMessage(feedback,'Upload received and is waiting for moderator review.');e.currentTarget.reset()});
});}

function streams(){entry('streams',async({root,configured})=>{
 root.insertAdjacentHTML('beforeend',`<section class="surface surface-pad"><h2 class="section-title">Submit a stream link</h2><p class="muted tiny">Use a public HTTPS link from Twitch, YouTube, or Kick. GameVault displays member-submitted links and does not guarantee that a stream is live.</p><form class="toolbar" id="stream-form"><input class="field" type="url" name="url" required placeholder="https://www.twitch.tv/yourchannel"><input class="field" name="title" maxlength="120" placeholder="Stream title"><button class="btn btn-primary">Add stream link</button></form><div id="stream-feedback"></div></section><h2 class="section-title" style="margin-top:22px">Member-submitted streams</h2><div id="stream-list"></div>`);
 const list=root.querySelector('#stream-list');
 if(!configured){list.innerHTML=state('No connected stream listings','Stream links load from Supabase. No example streams are shown.');root.querySelector('#stream-form button').disabled=true;return}
 const {data,error:loadError}=await supabase.from('stream_links').select('id,user_id,title,url,game_id,created_at,games(title)').eq('is_public',true).order('created_at',{ascending:false}).limit(30);if(loadError)throw loadError;
 const userIds=[...new Set((data||[]).map(x=>x.user_id))],profiles=userIds.length?await supabase.from('profile_cards').select('id,username,display_name,avatar_url').in('id',userIds):{data:[],error:null};if(profiles.error)throw profiles.error;const byId=new Map((profiles.data||[]).map(x=>[x.id,x]));
 list.innerHTML=data?.length?`<div class="grid grid-2">${data.map(s=>{const href=safeExternalHref(s.url),profile=byId.get(s.user_id);return `<article class="surface surface-pad"><p class="eyebrow">Member-submitted · ${escapeHTML(s.games?.title||'Game not specified')}</p><h3 class="section-title">${escapeHTML(s.title||'Stream link')}</h3><p class="muted tiny">${escapeHTML(profile?.display_name||profile?.username||'GameVault member')} · Link added ${date(s.created_at)}</p>${href?`<a class="btn btn-primary" href="${escapeHTML(href)}" target="_blank" rel="noopener noreferrer">Open stream ↗</a>`:'<span class="muted tiny">Invalid stream link</span>'}</article>`}).join('')}</div>`:state('No streams listed','When members add public stream links, they appear here.');
 root.querySelector('#stream-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,feedback=root.querySelector('#stream-feedback');let url;try{url=new URL(new FormData(form).get('url'))}catch{commonFormMessage(feedback,'Enter a valid URL.','error');return}if(url.protocol!=='https:'||!['twitch.tv','www.twitch.tv','youtube.com','www.youtube.com','youtu.be','kick.com','www.kick.com'].includes(url.hostname)){commonFormMessage(feedback,'Use an HTTPS link from Twitch, YouTube, or Kick.','error');return}const {data:{user}}=await getOptionalUser();if(!user){location.href='/pages/login.html';return}const {error:saveError}=await supabase.from('stream_links').insert({user_id:user.id,url:url.toString(),title:new FormData(form).get('title').toString().trim(),is_public:true});if(saveError)commonFormMessage(feedback,saveError.message,'error');else{commonFormMessage(feedback,'Stream link added. It is labeled member-submitted.');form.reset();location.reload()}})
});}
function messages(){entry('messages',async({root,configured})=>{if(!configured){root.insertAdjacentHTML('beforeend',state('Private messages need Supabase','Conversations and messages are never replaced with sample content.','<a class="btn" href="/pages/login.html">Sign in after setup</a>'));return}const user=await currentUser(true,root);if(!user)return;root.insertAdjacentHTML('beforeend',`<section class="surface surface-pad"><h2 class="section-title">Start a conversation</h2><form class="toolbar" id="new-conversation"><input class="field" name="username" placeholder="GameVault username" value="${escapeHTML(new URLSearchParams(location.search).get('username')||'')}" required><button class="btn">Find player</button></form><div id="new-conversation-feedback"></div></section><h2 class="section-title" style="margin-top:22px">Your conversations</h2><div id="conversation-list"></div>`);const list=root.querySelector('#conversation-list');const links=await supabase.from('conversation_members').select('conversation_id').eq('user_id',user.id).limit(100);if(links.error)throw links.error;if(!links.data.length)list.innerHTML=state('No conversations','A private conversation appears here after you start one with a public GameVault player.');else{const ids=links.data.map(x=>x.conversation_id);const conversations=await supabase.from('conversations').select('id,created_at,updated_at').in('id',ids).order('updated_at',{ascending:false});if(conversations.error)throw conversations.error;const participants=await supabase.from('conversation_members').select('conversation_id,user_id').in('conversation_id',ids);if(participants.error)throw participants.error;const otherIds=[...new Set(participants.data.filter(m=>m.user_id!==user.id).map(m=>m.user_id))];const people=otherIds.length?await supabase.from('profile_cards').select('id,username,display_name,avatar_url').in('id',otherIds):{data:[],error:null};if(people.error)throw people.error;const peopleById=new Map((people.data||[]).map(p=>[p.id,p]));const participantById=new Map();participants.data.forEach(m=>{if(!participantById.has(m.conversation_id))participantById.set(m.conversation_id,[]);participantById.get(m.conversation_id).push(m.user_id)});list.innerHTML=conversations.data.length?`<div class="data-list">${conversations.data.map(c=>{const otherId=(participantById.get(c.id)||[]).find(id=>id!==user.id),other=peopleById.get(otherId);return `<a class="data-row" href="/pages/messages.html?conversation=${encodeURIComponent(c.id)}">${avatarMarkup(other||{id:otherId},'gv-player-avatar','Player avatar')}<span class="grow"><h3>${escapeHTML(other?.display_name||other?.username||'Private conversation')}</h3><p>Open conversation · ${date(c.updated_at)}</p></span><span>→</span></a>`}).join('')}</div>`:state('No conversations','Start a private conversation with a public player.') }
  const id=new URLSearchParams(location.search).get('conversation');if(id){const membership=await supabase.from('conversation_members').select('conversation_id').eq('conversation_id',id).eq('user_id',user.id).maybeSingle();if(membership.error)throw membership.error;if(!membership.data){root.insertAdjacentHTML('beforeend',state('Conversation unavailable','This conversation is private to its participants.'));return}const msgBox=document.createElement('section');msgBox.className='surface surface-pad';msgBox.style.marginTop='18px';msgBox.innerHTML=`<h2 class="section-title">Conversation</h2><div id="message-list" class="data-list"></div><form id="message-send" class="toolbar"><input class="field" name="body" required maxlength="4000" placeholder="Write a private message"><button class="btn btn-primary">Send</button></form><div id="message-feedback"></div>`;root.append(msgBox);const messagesData=await supabase.from('messages').select('id,sender_id,body,created_at').eq('conversation_id',id).order('created_at',{ascending:true}).limit(100);if(messagesData.error)throw messagesData.error;msgBox.querySelector('#message-list').innerHTML=messagesData.data.length?messagesData.data.map(m=>`<article class="data-row"><span class="pill">${m.sender_id===user.id?'You':'Member'}</span><span class="grow"><p>${escapeHTML(m.body)}</p></span><time class="muted tiny">${date(m.created_at)}</time></article>`).join(''):state('No messages yet','Send the first message in this private conversation.');msgBox.querySelector('#message-send').addEventListener('submit',async e=>{e.preventDefault();const body=new FormData(e.currentTarget).get('body').toString().trim();const {error:saveError}=await supabase.from('messages').insert({conversation_id:id,sender_id:user.id,body});if(saveError)commonFormMessage(msgBox.querySelector('#message-feedback'),saveError.message,'error');else location.reload()})}
  root.querySelector('#new-conversation').addEventListener('submit',async e=>{e.preventDefault();const fb=root.querySelector('#new-conversation-feedback'),username=new FormData(e.currentTarget).get('username').toString().trim().replace(/^@/,'');const person=await supabase.from('profile_cards').select('id,username').eq('username',username).maybeSingle();if(person.error){commonFormMessage(fb,person.error.message,'error');return}if(!person.data){commonFormMessage(fb,'No public player found with that username.','error');return}if(person.data.id===user.id){commonFormMessage(fb,'Choose another GameVault player.','error');return}const conversation=await supabase.rpc('start_direct_conversation',{target_user:person.data.id});if(conversation.error){commonFormMessage(fb,conversation.error.message,'error');return}location.href='/pages/messages.html?conversation='+encodeURIComponent(conversation.data)});
});}

function notifications(){entry('notifications',async({root,configured})=>{
 if(!configured){root.insertAdjacentHTML('beforeend',state('Notifications are not connected','Connection invitations, replies, mentions, and moderation updates require your Supabase account.'));return}
 const user=await currentUser(true,root);if(!user)return;
  const [notifications,invitations,connectionRequests]=await Promise.all([
  supabase.from('notifications').select('id,kind,title,body,href,is_read,created_at').eq('user_id',user.id).order('created_at',{ascending:false}).limit(60),
   supabase.from('community_invitations').select('id,community_id,inviter_id,created_at,communities(name,slug)').eq('invitee_id',user.id).eq('status','pending').order('created_at',{ascending:false}).limit(30),
   supabase.from('connection_requests').select('id,sender_id,created_at').eq('recipient_id',user.id).eq('status','pending').order('created_at',{ascending:false}).limit(30)
 ]);if(notifications.error)throw notifications.error;if(invitations.error)throw invitations.error;
  if(connectionRequests.error)throw connectionRequests.error;const inviterIds=[...new Set([...(invitations.data||[]).map(i=>i.inviter_id),...(connectionRequests.data||[]).map(i=>i.sender_id)])],profiles=inviterIds.length?await supabase.from('profile_cards').select('id,username,display_name,avatar_url').in('id',inviterIds):{data:[],error:null};if(profiles.error)throw profiles.error;const people=new Map((profiles.data||[]).map(p=>[p.id,p]));
  root.insertAdjacentHTML('beforeend',`<section class="surface surface-pad"><h2 class="section-title">Connection requests</h2><div id="connection-request-list"></div></section><section class="surface surface-pad" style="margin-top:16px"><h2 class="section-title">Community invitations</h2><div id="invitation-list"></div></section><div class="toolbar" style="margin-top:18px"><button class="btn" id="mark-read">Mark all notifications as read</button></div><div id="notification-list"></div>`);
  const connectionBox=root.querySelector('#connection-request-list');connectionBox.innerHTML=connectionRequests.data?.length?`<div class="data-list">${connectionRequests.data.map(r=>{const person=people.get(r.sender_id);return `<article class="data-row">${avatarMarkup(person||{id:r.sender_id},'gv-player-avatar','Player avatar')}<span class="grow"><h3>${escapeHTML(person?.display_name||person?.username||'GameVault player')}</h3><p>Connection request · ${date(r.created_at)}</p>${person?`<a class="tiny" href="/pages/profile.html?username=${encodeURIComponent(person.username)}">View profile</a>`:''}</span><button class="btn connection-response" data-id="${r.id}" data-accept="false">Decline</button><button class="btn btn-primary connection-response" data-id="${r.id}" data-accept="true">Accept</button></article>`}).join('')}</div>`:state('No pending connection requests','Requests sent to you appear here. Only the recipient can accept or decline.');
 const invitationBox=root.querySelector('#invitation-list');invitationBox.innerHTML=invitations.data?.length?`<div class="data-list">${invitations.data.map(i=>{const person=people.get(i.inviter_id);return `<article class="data-row">${avatarMarkup(person||{id:i.inviter_id},'gv-player-avatar','Inviting player avatar')}<span class="grow"><h3>${escapeHTML(i.communities?.name||'Community invitation')}</h3><p>${escapeHTML(person?.display_name||person?.username||'GameVault member')} invited you · ${date(i.created_at)}</p></span><button class="btn invitation-response" data-id="${i.id}" data-accept="false">Decline</button><button class="btn btn-primary invitation-response" data-id="${i.id}" data-accept="true">Accept</button></article>`}).join('')}</div>`:state('No pending invitations','Community invitations sent to your public profile will appear here.');
 const list=root.querySelector('#notification-list');list.innerHTML=notifications.data?.length?`<div class="data-list">${notifications.data.map(n=>`<article class="data-row"><span class="pill">${n.is_read?'○':'●'}</span><span class="grow"><h3>${escapeHTML(n.title)}</h3><p>${escapeHTML(n.body||n.kind)} · ${date(n.created_at)}</p></span>${safeInternalHref(n.href)?`<a class="btn" href="${escapeHTML(safeInternalHref(n.href))}">Open</a>`:''}</article>`).join('')}</div>`:state('You are all caught up','Replies, mentions, and moderation updates will appear here when real activity happens.');
 root.querySelectorAll('.invitation-response').forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;const {data:slug,error:responseError}=await supabase.rpc('respond_to_community_invitation',{invitation_id:button.dataset.id,accept_invitation:button.dataset.accept==='true'});if(responseError){button.disabled=false;alert(responseError.message);return}if(button.dataset.accept==='true')location.href='/pages/community.html?slug='+encodeURIComponent(slug);else location.reload()}));
  root.querySelectorAll('.connection-response').forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;const {error:responseError}=await supabase.rpc('respond_to_connection_request',{request_id:button.dataset.id,accept_request:button.dataset.accept==='true'});if(responseError){button.disabled=false;alert(responseError.message);return}location.reload()}));
 root.querySelector('#mark-read').addEventListener('click',async()=>{const {error:e}=await supabase.from('notifications').update({is_read:true}).eq('user_id',user.id).eq('is_read',false);if(e)alert('Could not update notifications: '+e.message);else location.reload()});
});}
function challenges(){entry('challenges',async({root,configured})=>{
  if(!configured){root.insertAdjacentHTML('beforeend',state('Challenge rankings need Supabase','There are no sample competitions or results. Real challenges and member-entered results will load from the database.'));return}
  const {data:{user},error:authError}=await getOptionalUser();if(authError)throw authError;
  let canCreate=false;if(user){const role=await supabase.from('user_roles').select('role').eq('user_id',user.id).in('role',['moderator','admin']).limit(1);if(role.error)throw role.error;canCreate=Boolean(role.data?.length)}
  if(canCreate){const games=await supabase.from('games').select('id,title').order('title').limit(300);if(games.error)throw games.error;const start=new Date(Date.now()+3600000),end=new Date(Date.now()+7*86400000);root.insertAdjacentHTML('beforeend',`<section class="surface surface-pad" style="margin-bottom:18px"><h2 class="section-title">Publish a challenge</h2><p class="muted tiny">Moderator-created GameVault challenge. Player results are self-reported and are not verified game statistics.</p><form id="challenge-create" class="form-stack"><label class="field-wrap">Title<input class="field" name="title" minlength="3" maxlength="120" required></label><label class="field-wrap">Description<textarea class="textarea" name="description" maxlength="2000"></textarea></label><label class="field-wrap">Grand Theft Auto title<select class="select" name="game_id" required>${games.data.map(g=>`<option value="${g.id}">${escapeHTML(g.title)}</option>`).join('')}</select></label><label class="field-wrap">Scoring rule<select class="select" name="result_order" required><option value="">Choose how results rank</option><option value="highest">Highest value wins</option><option value="lowest">Lowest value wins</option></select></label><div class="grid grid-2"><label class="field-wrap">Starts<input class="field" name="starts_at" type="datetime-local" value="${start.toISOString().slice(0,16)}" required></label><label class="field-wrap">Ends<input class="field" name="ends_at" type="datetime-local" value="${end.toISOString().slice(0,16)}" required></label></div><div id="challenge-create-feedback"></div><button class="btn btn-primary">Publish challenge</button></form></section>`)}
  const challenges=await supabase.from('challenges').select('id,title,description,game_id,result_order,starts_at,ends_at,games(title)').eq('is_public',true).gte('ends_at',new Date().toISOString()).order('starts_at',{ascending:true}).limit(50);if(challenges.error)throw challenges.error;
  if(!challenges.data?.length)root.insertAdjacentHTML('beforeend',state('No upcoming challenges','Public GameVault challenges appear here when a moderator publishes them.'));
  else{
   const entries=await supabase.from('challenge_entries').select('challenge_id,user_id,result_value,result_label,submitted_at').in('challenge_id',challenges.data.map(c=>c.id)).order('result_value',{ascending:false}).limit(100);if(entries.error)throw entries.error;
   const challengeUserIds=[...new Set((entries.data||[]).map(x=>x.user_id))],challengeProfiles=challengeUserIds.length?await supabase.from('profile_cards').select('id,username,display_name,avatar_url').in('id',challengeUserIds):{data:[],error:null};if(challengeProfiles.error)throw challengeProfiles.error;const challengeProfileById=new Map((challengeProfiles.data||[]).map(x=>[x.id,x]));
   root.insertAdjacentHTML('beforeend',`<div class="grid grid-2">${challenges.data.map(c=>{const rows=entries.data.filter(x=>x.challenge_id===c.id).sort((a,b)=>c.result_order==='lowest'?Number(a.result_value)-Number(b.result_value):Number(b.result_value)-Number(a.result_value)),active=Date.now()>=new Date(c.starts_at).getTime()&&Date.now()<=new Date(c.ends_at).getTime();return `<section class="surface surface-pad"><p class="eyebrow">${escapeHTML(c.games?.title||'GameVault challenge')} · Player-entered</p><h2 class="section-title">${escapeHTML(c.title)}</h2><p class="muted tiny">${escapeHTML(c.description||'')}</p><p class="muted tiny">${date(c.starts_at)} – ${date(c.ends_at)} · ${active?'Open now':'Upcoming'} · ${c.result_order==='lowest'?'Lowest value wins':'Highest value wins'}</p><div class="table-wrap"><table class="table"><thead><tr><th>Player</th><th>Result</th><th>Submitted</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td>${escapeHTML(challengeProfileById.get(r.user_id)?.display_name||challengeProfileById.get(r.user_id)?.username||'GameVault member')}</td><td>${escapeHTML(r.result_label||String(r.result_value))}</td><td>${date(r.submitted_at)}</td></tr>`).join(''):'<tr><td colspan="3">No entries yet.</td></tr>'}</tbody></table></div><form class="challenge-entry toolbar" data-id="${c.id}"><input class="field" name="result" type="number" step="any" required placeholder="Your result" ${active?'':'disabled'}><button class="btn" ${active?'':'disabled'}>Submit your result</button></form><p class="muted tiny">Your result is marked as player-entered; GameVault does not verify official game stats.</p></section>`}).join('')}</div>`);
   root.querySelectorAll('.challenge-entry').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();if(!user){location.href='/pages/login.html';return}const value=Number(new FormData(form).get('result'));const {error:saveError}=await supabase.from('challenge_entries').upsert({challenge_id:form.dataset.id,user_id:user.id,result_value:value,result_label:String(value),is_user_entered:true},{onConflict:'challenge_id,user_id'});if(saveError)commonFormMessage(form,saveError.message,'error');else location.reload()}));
  }
  root.querySelector('#challenge-create')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,fd=new FormData(form),starts_at=new Date(fd.get('starts_at')).toISOString(),ends_at=new Date(fd.get('ends_at')).toISOString(),feedback=root.querySelector('#challenge-create-feedback');if(ends_at<=starts_at){commonFormMessage(feedback,'The end time must be after the start time.','error');return}const {error:createError}=await supabase.from('challenges').insert({created_by:user.id,game_id:fd.get('game_id')||null,title:fd.get('title').toString().trim(),description:fd.get('description').toString().trim(),result_order:fd.get('result_order'),is_public:true,starts_at,ends_at});if(createError)commonFormMessage(feedback,createError.message,'error');else{commonFormMessage(feedback,'Challenge published.');location.reload()}});
});}

function historyPage(){entry('history',async({root,configured})=>{if(!configured){root.insertAdjacentHTML('beforeend',state('History requires a connected account','GameVault does not invent achievement or play data. Your real milestones and self-entered notes will load here.'));return}const user=await currentUser(true,root);if(!user)return;const [achievements,history]=await Promise.all([supabase.from('user_achievements').select('id,title,description,awarded_at,is_user_entered').eq('user_id',user.id).order('awarded_at',{ascending:false}).limit(100),supabase.from('gaming_history').select('id,title,note,occurred_at,source,is_user_entered').eq('user_id',user.id).order('occurred_at',{ascending:false}).limit(100)]);if(achievements.error)throw achievements.error;if(history.error)throw history.error;root.insertAdjacentHTML('beforeend',`<div class="grid grid-2"><section class="surface surface-pad"><h2 class="section-title">Achievements</h2>${achievements.data.length?`<div class="data-list">${achievements.data.map(a=>infoRow(a.title,a.description||'Milestone',a.is_user_entered?'✎':'✦',`${a.is_user_entered?'Player-entered · ':''}${date(a.awarded_at)}`)).join('')}</div>`:state('No achievements yet','Verified integrations are not offered. You may record your own milestone below.')}</section><section class="surface surface-pad"><h2 class="section-title">Gaming history</h2><div id="history-list">${history.data.length?`<div class="data-list">${history.data.map(h=>infoRow(h.title,h.note||'Personal history entry','◷',`Player-entered · ${date(h.occurred_at)}`)).join('')}</div>`:state('No history notes yet','Add a personal gaming milestone. Entries are marked player-entered.')}</div><form id="history-form" class="form-stack"><label class="field-wrap">Milestone title<input class="field" name="title" maxlength="100" required></label><label class="field-wrap">Note<textarea class="textarea" name="note" maxlength="1000"></textarea></label><label class="field-wrap">Date<input class="field" name="occurred_at" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><button class="btn btn-primary">Add player-entered milestone</button><div id="history-feedback"></div></form></section></div>`);root.querySelector('#history-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const {error:saveError}=await supabase.from('gaming_history').insert({user_id:user.id,title:fd.get('title').toString().trim(),note:fd.get('note').toString().trim(),occurred_at:fd.get('occurred_at'),source:'player-entered',is_user_entered:true});if(saveError)commonFormMessage(root.querySelector('#history-feedback'),saveError.message,'error');else location.reload()})});}

function account(){entry('account',async({root,configured})=>{if(!configured){root.insertAdjacentHTML('beforeend',state('Account area is not connected','Connect Supabase before using real accounts or private settings.',authPrompt()));return}const user=await currentUser(true,root);if(!user)return;const {data:p,error:e}=await loadCurrentProfile(user.id);if(e)throw e;const cards=[['Profile details','Update username, avatar, bio, games, and platforms','/pages/account/profile.html'],['Privacy','Choose profile visibility and field-level choices','/pages/account/privacy.html'],['Security','Verified email and password','/pages/account/security.html'],['Notification preferences','Control notification categories','/pages/account/notifications.html'],['Game library','Add games, favorites, and current play status','/pages/account/games.html'],['Delete account','Start the confirmed deletion process','/pages/account/delete.html']];root.insertAdjacentHTML('beforeend',`<section class="surface surface-pad"><p class="eyebrow">SIGNED IN</p><h2 class="section-title">${escapeHTML(p?.display_name||p?.username||user.email||'GameVault member')}</h2><p class="muted tiny">Account ID ${escapeHTML(user.id)} · email ${escapeHTML(user.email||'not available')} · verification ${user.email_confirmed_at?'verified':'pending'}</p><div class="row"><a class="btn" href="/pages/profile.html?username=${encodeURIComponent(p?.username||'')}">View public profile</a><button class="btn" id="sign-out">Sign out</button></div></section><div class="grid grid-3" style="margin-top:18px">${cards.map(([title,desc,url])=>`<a class="surface surface-pad" href="${url}"><span class="pill">Account control</span><h2 class="section-title" style="margin-top:13px">${title}</h2><p class="muted tiny">${desc}</p><span class="btn">Open →</span></a>`).join('')}</div>`);root.querySelector('#sign-out').addEventListener('click',async()=>{const {error:signOutError}=await supabase.auth.signOut();if(signOutError)alert(signOutError.message);else location.href='/pages/login.html'})});}

function accountProfile(){
 entry('account-profile',async({root,configured})=>{
  if(!configured){root.insertAdjacentHTML('beforeend',state('Profile editing is not available yet','Configure Supabase and sign in to save profile changes.'));return}
  const user=await currentUser(true,root);if(!user)return;
  const {data:p,error:e}=await loadCurrentProfile(user.id);if(e)throw e;
  if(!p){root.insertAdjacentHTML('beforeend',error('Your profile row is missing. Apply the profile trigger migration or ask an administrator to repair it.'));return}
  const avatars=avatarPresets();
  const platforms=await supabase.from('platforms').select('id,name').order('name');if(platforms.error)throw platforms.error;
  const selected=await supabase.from('user_platforms').select('platform_id').eq('user_id',user.id);if(selected.error)throw selected.error;
  const chosen=new Set((selected.data||[]).map(x=>x.platform_id));
   root.insertAdjacentHTML('beforeend',`<section class="surface surface-pad"><form id="profile-form" class="form-stack"><label class="field-wrap">Username<input class="field" name="username" minlength="3" maxlength="24" pattern="[A-Za-z0-9_]+" value="${escapeHTML(p.username)}" required><span class="muted tiny">3–24 letters, numbers, or underscores.</span></label><label class="field-wrap">Display name<input class="field" name="display_name" maxlength="60" value="${escapeHTML(p.display_name||'')}" required></label><label class="field-wrap">Bio<textarea class="textarea" name="bio" maxlength="280">${escapeHTML(p.bio||'')}</textarea></label><label class="field-wrap">Upload an avatar (JPG, PNG, WebP; up to 5 MB)<input class="field" id="avatar-upload" type="file" accept="image/jpeg,image/png,image/webp"></label><input type="hidden" id="avatar-url" value="${escapeHTML(p.avatar_url||'')}"><p class="muted tiny">Or choose an optional portrait preset from the supplied image set. These images do not represent GameVault accounts.</p><div class="grid grid-4">${avatars.map(a=>`<button type="button" class="avatar-option ${p.avatar_url===a.src?'selected':''}" data-src="${a.src}"><img src="${a.src}" alt="Portrait preset ${escapeHTML(a.name)}"><span class="tiny">${escapeHTML(a.name)}</span></button>`).join('')}</div><h2 class="section-title">Your platforms</h2><p class="muted tiny">These selected platform tags are saved to your account. Game selection is managed in your library.</p><div class="grid grid-3">${platforms.data.map(x=>`<label class="check-line"><input type="checkbox" name="platform_id" value="${x.id}" ${chosen.has(x.id)?'checked':''}>${escapeHTML(x.name)}</label>`).join('')}</div><a class="btn" href="/pages/account/games.html">Choose games →</a><div id="profile-feedback"></div><button class="btn btn-primary">Save profile and platforms</button></form></section>`);
   const avatarGrid=root.querySelector('.avatar-option')?.parentElement;
   if(avatarGrid){
    const label=root.querySelector('#avatar-url + p');
    if(label)label.textContent='Choose a GTA-world inspired crew role, upload your own, or use the generated default. These are original GameVault portraits, not Rockstar characters or demo accounts.';
    avatarGrid.innerHTML=avatars.map(a=>`<button type="button" class="avatar-option ${p.avatar_url===a.src?'selected':''}" aria-pressed="${p.avatar_url===a.src}" aria-label="Choose ${escapeHTML(a.label)} avatar" data-src="${a.src}"><img src="${a.src}" alt=""><span class="tiny">${escapeHTML(a.label)}</span></button>`).join('');
    const controls=document.createElement('div');controls.className='gv-avatar-controls';controls.innerHTML=`<div class="gv-avatar-preview" id="avatar-preview">${avatarMarkup({...p,id:user.id},'gv-avatar-preview-image','Current player avatar')}</div><button type="button" class="btn" id="use-default-avatar">Use my generated default</button><span class="muted tiny">The choice is saved to your existing profile avatar field.</span>`;
    avatarGrid.before(controls);
   }
   const socialSection=document.createElement('section');socialSection.className='form-stack';socialSection.innerHTML=`<div><h2 class="section-title">Social links</h2><p class="muted tiny">Add HTTPS links to your profiles. Choose whether they appear publicly in Privacy settings.</p></div>${socialNetworks.map(([key,label,hosts])=>`<label class="field-wrap">${label}<input class="field" type="url" name="social_${key}" inputmode="url" placeholder="https://${hosts[0]}/yourname" value="${escapeHTML(p.social_links?.[key]||'')}"></label>`).join('')}`;
   root.querySelector('#profile-form').querySelector('h2').before(socialSection);
  root.querySelectorAll('.avatar-option').forEach(b=>b.addEventListener('click',()=>{root.querySelectorAll('.avatar-option').forEach(x=>{x.classList.remove('selected');x.setAttribute('aria-pressed','false')});b.classList.add('selected');b.setAttribute('aria-pressed','true');root.querySelector('#avatar-url').value=b.dataset.src;root.querySelector('#avatar-preview img')?.setAttribute('src',b.dataset.src)}));
  root.querySelector('#use-default-avatar')?.addEventListener('click',()=>{root.querySelector('#avatar-url').value='';root.querySelectorAll('.avatar-option').forEach(x=>{x.classList.remove('selected');x.setAttribute('aria-pressed','false')});root.querySelector('#avatar-preview img')?.setAttribute('src',avatarSource({id:user.id}))});
  root.querySelector('#avatar-upload').addEventListener('change',async e=>{const file=e.target.files[0],feedback=root.querySelector('#profile-feedback');if(!file)return;if(!allowedFile(file,false)){commonFormMessage(feedback,'Choose a JPG, PNG, or WebP smaller than 5 MB.','error');return}const ext=file.name.split('.').pop().toLowerCase(),path=`${user.id}/avatar-${crypto.randomUUID()}.${ext}`;const up=await supabase.storage.from('vexra-avatars').upload(path,file,{contentType:file.type,upsert:false});if(up.error){commonFormMessage(feedback,up.error.message,'error');return}const url=supabase.storage.from('vexra-avatars').getPublicUrl(path).data.publicUrl;root.querySelector('#avatar-url').value=url;root.querySelector('#avatar-preview img')?.setAttribute('src',url);root.querySelectorAll('.avatar-option').forEach(x=>{x.classList.remove('selected');x.setAttribute('aria-pressed','false')});commonFormMessage(feedback,'Avatar uploaded. Save the profile to apply it.')});
   root.querySelector('#profile-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),feedback=root.querySelector('#profile-feedback'),social_links=Object.fromEntries(socialNetworks.map(([key])=>[key,fd.get(`social_${key}`).toString().trim()]));for(const [key,value] of Object.entries(social_links)){if(!validSocialURL(key,value)){commonFormMessage(feedback,`Enter a valid HTTPS ${socialNetworks.find(x=>x[0]===key)[1]} link.`,'error');return}}const result=await updateProfile(user.id,{username:fd.get('username').toString().trim().toLowerCase(),display_name:fd.get('display_name').toString().trim(),bio:fd.get('bio').toString().trim(),avatar_url:root.querySelector('#avatar-url').value||null,social_links});if(result.error){commonFormMessage(feedback,result.error.message,'error');return}const platformIds=fd.getAll('platform_id').map(String);const cleared=await supabase.from('user_platforms').delete().eq('user_id',user.id);if(cleared.error){commonFormMessage(feedback,cleared.error.message,'error');return}if(platformIds.length){const saved=await supabase.from('user_platforms').insert(platformIds.map(platform_id=>({user_id:user.id,platform_id})));if(saved.error){commonFormMessage(feedback,saved.error.message,'error');return}}commonFormMessage(feedback,'Profile, social links, and platform selections saved.')});
 });
}
function accountPrivacy(){entry('account-privacy',async({root,configured})=>{
  if(!configured){root.insertAdjacentHTML('beforeend',state('Privacy settings need Supabase','Connect the database before changing profile visibility.'));return}
  const user=await currentUser(true,root);if(!user)return;
  const {data:p,error:e}=await supabase.from('profile_privacy').select('visibility,field_visibility').eq('user_id',user.id).maybeSingle();if(e)throw e;const f=p?.field_visibility||{};
  root.insertAdjacentHTML('beforeend',`<section class="surface surface-pad"><form id="privacy-form" class="form-stack"><label class="field-wrap">Profile visibility<select class="select" name="visibility"><option value="private" ${p?.visibility!=='public'?'selected':''}>Private — only you</option><option value="public" ${p?.visibility==='public'?'selected':''}>Public — visible in GameVault directories</option></select></label><p class="muted tiny">Email, account settings, messages, and security information are never shown on public profile pages.</p>${[['bio','Show bio publicly'],['games','Show selected games publicly'],['achievements','Show achievements publicly'],['platforms','Show selected platforms publicly'],['socials','Show social links publicly'],['connections','Show connections publicly']].map(([key,label])=>`<label class="check-line"><input type="checkbox" name="${key}" ${f[key]?'checked':''}>${label}</label>`).join('')}<div id="privacy-feedback"></div><button class="btn btn-primary">Save privacy settings</button></form></section>`);
  root.querySelector('#privacy-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const field_visibility=Object.fromEntries(['bio','games','achievements','platforms','socials','connections'].map(k=>[k,fd.has(k)]));const {error:saveError}=await supabase.from('profile_privacy').upsert({user_id:user.id,visibility:fd.get('visibility'),field_visibility},{onConflict:'user_id'});commonFormMessage(root.querySelector('#privacy-feedback'),saveError?.message||'Privacy choices saved.',saveError?'error':'success')});
  const [blocks,mutes]=await Promise.all([supabase.from('user_blocks').select('blocked_id,created_at').eq('blocker_id',user.id),supabase.from('user_mutes').select('muted_id,created_at').eq('muter_id',user.id)]);if(blocks.error)throw blocks.error;if(mutes.error)throw mutes.error;
  const controls=document.createElement('section');controls.className='surface surface-pad';controls.style.marginTop='18px';controls.innerHTML=`<h2 class="section-title">Blocked accounts</h2><p class="muted tiny">Blocked profiles and posts are hidden from your view. Unblock a player here.</p>${blocks.data.length?`<div class="data-list">${blocks.data.map(x=>`<div class="data-row"><span class="grow"><strong>GameVault account ${escapeHTML(x.blocked_id.slice(0,8))}</strong><p>Blocked ${date(x.created_at)}</p></span><button class="btn unblock-user" data-id="${x.blocked_id}">Unblock</button></div>`).join('')}</div>`:state('No blocked accounts','You have not blocked any GameVault accounts.')}<h2 class="section-title" style="margin-top:20px">Muted accounts</h2><p class="muted tiny">Muted players’ posts and replies are hidden from your feed.</p>${mutes.data.length?`<div class="data-list">${mutes.data.map(x=>`<div class="data-row"><span class="grow"><strong>GameVault account ${escapeHTML(x.muted_id.slice(0,8))}</strong><p>Muted ${date(x.created_at)}</p></span><button class="btn unmute-user" data-id="${x.muted_id}">Unmute</button></div>`).join('')}</div>`:state('No muted accounts','You have not muted any GameVault accounts.')}`;root.append(controls);
  controls.querySelectorAll('.unblock-user').forEach(button=>button.addEventListener('click',async()=>{const {error:removeError}=await supabase.from('user_blocks').delete().eq('blocker_id',user.id).eq('blocked_id',button.dataset.id);if(removeError)alert(removeError.message);else location.reload()}));
  controls.querySelectorAll('.unmute-user').forEach(button=>button.addEventListener('click',async()=>{const {error:removeError}=await supabase.from('user_mutes').delete().eq('muter_id',user.id).eq('muted_id',button.dataset.id);if(removeError)alert(removeError.message);else location.reload()}));
});}

function accountSecurity(){entry('account-security',async({root,configured})=>{if(!configured){root.insertAdjacentHTML('beforeend',state('Security settings need Supabase Auth','Passwords are managed by Supabase Auth, never by a GameVault database table.'));return}const user=await currentUser(true,root);if(!user)return;root.insertAdjacentHTML('beforeend',`<div class="grid grid-2"><section class="surface surface-pad"><h2 class="section-title">Email address</h2><p class="muted tiny">Current address: ${escapeHTML(user.email||'Not available')}</p><p class="muted tiny">Status: ${user.email_confirmed_at?'Verified':'Verification pending'}</p><form id="email-form" class="form-stack"><label class="field-wrap">Change email<input class="field" name="email" type="email" required></label><button class="btn">Send verification to new address</button><div id="email-feedback"></div></form></section><section class="surface surface-pad"><h2 class="section-title">Password</h2><form id="password-form" class="form-stack"><label class="field-wrap">New password<input class="field" name="password" type="password" minlength="10" autocomplete="new-password" required></label><label class="field-wrap">Repeat password<input class="field" name="confirm" type="password" minlength="10" autocomplete="new-password" required></label><button class="btn btn-primary">Change password</button><div id="password-feedback"></div></form></section></div>`);root.querySelector('#email-form').addEventListener('submit',async e=>{e.preventDefault();const email=new FormData(e.currentTarget).get('email').toString().trim();const {error:saveError}=await supabase.auth.updateUser({email});commonFormMessage(root.querySelector('#email-feedback'),saveError?.message||'Check the new inbox to verify this email.',saveError?'error':'success')});root.querySelector('#password-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);if(fd.get('password')!==fd.get('confirm')){commonFormMessage(root.querySelector('#password-feedback'),'Passwords do not match.','error');return}const {error:saveError}=await supabase.auth.updateUser({password:fd.get('password').toString()});commonFormMessage(root.querySelector('#password-feedback'),saveError?.message||'Password updated.',saveError?'error':'success')})});}

function accountNotifications(){entry('account-notifications',async({root,configured})=>{if(!configured){root.insertAdjacentHTML('beforeend',state('Notification settings need Supabase','Connect your account before loading or saving preferences.'));return}const user=await currentUser(true,root);if(!user)return;const {data:p,error:e}=await supabase.from('account_preferences').select('notification_preferences').eq('user_id',user.id).maybeSingle();if(e)throw e;const prefs=p?.notification_preferences||{};const keys=[['replies','Replies to your posts'],['mentions','Mentions'],['connections','Connection requests'],['community_invites','Community invitations'],['community_join_requests','Community join requests'],['moderation','Moderation updates'],['messages','Private messages']];root.insertAdjacentHTML('beforeend',`<section class="surface surface-pad"><form id="preferences-form" class="form-stack"><h2 class="section-title">In-app notifications</h2>${keys.map(([k,l])=>`<label class="check-line"><input type="checkbox" name="${k}" ${prefs[k]!==false?'checked':''}>${l}</label>`).join('')}<div id="preferences-feedback"></div><button class="btn btn-primary">Save preferences</button></form></section>`);root.querySelector('#preferences-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),notification_preferences=Object.fromEntries(keys.map(([k])=>[k,fd.has(k)]));const {error:saveError}=await supabase.from('account_preferences').upsert({user_id:user.id,notification_preferences},{onConflict:'user_id'});commonFormMessage(root.querySelector('#preferences-feedback'),saveError?.message||'Notification preferences saved.',saveError?'error':'success')})});}

function accountGames(){entry('account-games',async({root,configured})=>{if(!configured){root.insertAdjacentHTML('beforeend',state('Your library needs Supabase','The catalog preview is available at Games. Sign in after connecting Supabase to save a personal library.','<a class="btn" href="/games/index.html">Browse game catalog</a>'));return}const user=await currentUser(true,root);if(!user)return;const {data:rows,error:loadError}=await supabase.from('user_games').select('game_id,is_favorite,is_currently_playing,added_at,games!inner(id,slug,title,genre,franchise)').eq('user_id',user.id).eq('games.franchise','grand-theft-auto').order('added_at',{ascending:false});if(loadError)throw loadError;root.insertAdjacentHTML('beforeend',`<section class="surface surface-pad"><h2 class="section-title">Add a game</h2><form id="library-search" class="toolbar"><input class="field" name="q" placeholder="Search GTA game catalog"><button class="btn">Find games</button></form><div id="library-results"></div></section><h2 class="section-title" style="margin-top:22px">Your library</h2><div id="my-games"></div>`);const list=root.querySelector('#my-games');function draw(data){list.innerHTML=data?.length?`<div class="grid grid-3">${data.map(r=>`<article class="surface surface-pad"><p class="eyebrow">${escapeHTML(r.games?.genre||'Game')}</p><h3 class="section-title"><a href="/games/${encodeURIComponent(r.games?.slug||'')}/">${escapeHTML(r.games?.title||'Game')}</a></h3><label class="check-line"><input type="checkbox" class="favorite" data-id="${r.game_id}" ${r.is_favorite?'checked':''}>Favorite</label><label class="check-line"><input type="checkbox" class="playing" data-id="${r.game_id}" ${r.is_currently_playing?'checked':''}>Currently playing</label><button class="btn remove-game" data-id="${r.game_id}">Remove</button></article>`).join('')}</div>`:state('Your library is empty','Search the catalog above and add the games you play.');list.querySelectorAll('.favorite,.playing').forEach(input=>input.addEventListener('change',async()=>{const row=data.find(x=>x.game_id===input.dataset.id);const patch=input.classList.contains('favorite')?{is_favorite:input.checked}:{is_currently_playing:input.checked};const {error:saveError}=await setGameSelection(user.id,input.dataset.id,patch);if(saveError){input.checked=!input.checked;input.title=saveError.message}else{row[input.classList.contains('favorite')?'is_favorite':'is_currently_playing']=input.checked}}));list.querySelectorAll('.remove-game').forEach(btn=>btn.addEventListener('click',async()=>{const {error:deleteError}=await supabase.from('user_games').delete().eq('user_id',user.id).eq('game_id',btn.dataset.id);if(deleteError)alert(deleteError.message);else draw(data.filter(x=>x.game_id!==btn.dataset.id))}))}draw(rows);root.querySelector('#library-search').addEventListener('submit',async e=>{e.preventDefault();const q=new FormData(e.currentTarget).get('q').toString().trim();const target=root.querySelector('#library-results');if(!q){target.innerHTML='';return}const {data:games,error:findError}=await supabase.from('games').select('id,title,slug,genre').ilike('title',`%${q.replace(/[%_,]/g,'')}%`).limit(12);if(findError){target.innerHTML=error(findError.message);return}target.innerHTML=games?.length?`<div class="data-list">${games.map(g=>`<div class="data-row"><span class="grow"><h3>${escapeHTML(g.title)}</h3><p>${escapeHTML(g.genre||'')}</p></span><button class="btn add-game" data-id="${g.id}">Add</button></div>`).join('')}</div>`:state('No games found','Try another title.');target.querySelectorAll('.add-game').forEach(btn=>btn.addEventListener('click',async()=>{const {error:saveError}=await setGameSelection(user.id,btn.dataset.id,{is_favorite:false,is_currently_playing:false});if(saveError)alert(saveError.message);else location.reload()}))})});}

function settings(){entry('settings',async({root,configured})=>{if(!configured){root.insertAdjacentHTML('beforeend',state('Settings live in your account area','Connect Supabase and sign in to manage personal settings.',authPrompt()));return}const user=await currentUser(true,root);if(!user)return;root.innerHTML=`<div class="grid grid-3">${[['Profile','Name, username, bio, avatar, and platforms','/pages/account/profile.html'],['Privacy','Visibility and public profile fields','/pages/account/privacy.html'],['Security','Password and verified email','/pages/account/security.html'],['Notifications','Notification preferences','/pages/account/notifications.html'],['Games','Personal game library','/pages/account/games.html'],['Account','Overview and account deletion','/pages/account.html']].map(([a,b,c])=>cardLink(a,c,b,'⚙')).join('')}</div>`});}

function accountDelete(){entry('account-delete',async({root,configured})=>{if(!configured){root.insertAdjacentHTML('beforeend',state('Deletion requires the configured backend','The deletion action runs in a server-side Supabase Edge Function. No account can be deleted from this offline preview.'));return}const user=await currentUser(true,root);if(!user)return;root.insertAdjacentHTML('beforeend',`<section class="surface surface-pad"><div class="notice">Deleting your account is permanent. GameVault will remove your profile and account-owned records, then sign you out. Back up anything you want to keep first.</div><form id="delete-form" class="form-stack" style="margin-top:18px"><label class="field-wrap">Type DELETE to confirm<input class="field" name="confirm" autocomplete="off" required></label><label class="check-line"><input type="checkbox" name="understand" required>I understand this permanently deletes my GameVault account and associated data.</label><div id="delete-feedback"></div><button class="btn btn-danger">Permanently delete account</button></form></section>`);root.querySelector('#delete-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);if(fd.get('confirm')!=='DELETE'){commonFormMessage(root.querySelector('#delete-feedback'),'Enter DELETE exactly to confirm.','error');return}const button=e.currentTarget.querySelector('button');button.disabled=true;button.textContent='Deleting account…';const {error:deleteError}=await supabase.functions.invoke('delete-account',{body:{confirm:'DELETE'}});if(deleteError){button.disabled=false;button.textContent='Permanently delete account';commonFormMessage(root.querySelector('#delete-feedback'),deleteError.message,'error');return}await supabase.auth.signOut();root.innerHTML=success('Account deleted.');setTimeout(()=>location.href='/pages/home.html',1500)})});}

function moderation(){entry('moderation',async({root,configured})=>{if(!configured){root.insertAdjacentHTML('beforeend',state('Moderation requires authenticated roles','No report samples are shown. The dashboard appears only to accounts with a moderator role in Supabase.'));return}const user=await currentUser(true,root);if(!user)return;const role=await supabase.from('user_roles').select('role').eq('user_id',user.id).eq('role','moderator').maybeSingle();if(role.error)throw role.error;if(!role.data){root.innerHTML=state('Moderator access required','Your account does not have the moderator role. Moderation permissions are enforced by database policies.');return}const {data:reports,error:loadError}=await supabase.from('moderation_reports').select('id,subject_type,subject_id,reason,status,created_at').order('created_at',{ascending:true}).limit(100);if(loadError)throw loadError;root.insertAdjacentHTML('beforeend',reports?.length?`<div class="data-list">${reports.map(r=>`<article class="surface surface-pad"><p class="eyebrow">${escapeHTML(r.subject_type)} · ${escapeHTML(r.status)}</p><p>${escapeHTML(r.reason)}</p><p class="muted tiny">Report ID ${escapeHTML(r.id)} · ${date(r.created_at)}</p><div class="row"><button class="btn report-action" data-id="${r.id}" data-status="reviewed">Mark reviewed</button><button class="btn report-action" data-id="${r.id}" data-status="actioned">Action taken</button><button class="btn report-action" data-id="${r.id}" data-status="dismissed">Dismiss</button></div></article>`).join('')}</div>`:state('No reports','The moderation queue is clear.'));root.querySelectorAll('.report-action').forEach(btn=>btn.addEventListener('click',async()=>{const {error:updateError}=await supabase.from('moderation_reports').update({status:btn.dataset.status,resolved_by:user.id,resolved_at:new Date().toISOString()}).eq('id',btn.dataset.id);if(updateError)alert(updateError.message);else location.reload()}))});}

function help(){entry('guidelines',async({root})=>{root.innerHTML=`<div class="grid grid-2"><section class="surface surface-pad"><h2 class="section-title">Community guidelines</h2><ol class="muted tiny"><li>Respect other players and creators.</li><li>Keep posts relevant to their community.</li><li>Do not share another person’s private information.</li><li>Label player-entered achievements, clips, and results honestly.</li><li>Do not impersonate a publisher, streamer, or another member.</li><li>Report harassment, spam, unsafe media, or suspicious links for moderator review.</li></ol></section><section class="surface surface-pad"><h2 class="section-title">Reporting and safety</h2><p class="muted tiny">Use the Report action on a community or player profile. Reports are sent to authorized GameVault moderators. Never post passwords, email verification links, payment details, or private addresses.</p><a class="btn" href="/pages/communities.html">Browse communities</a><a class="btn" href="/pages/account/privacy.html">Privacy settings</a></section><section class="surface surface-pad"><h2 class="section-title">Account help</h2><p class="muted tiny">Forgot your password? Request a reset link from Supabase Auth. Email changes require verification. Account deletion requires typing DELETE and deploying the supplied server-side function.</p><div class="row"><a class="btn" href="/pages/forgot-password.html">Password help</a><a class="btn" href="/pages/account/security.html">Security settings</a></div></section><section class="surface surface-pad"><h2 class="section-title">Support</h2><p class="muted tiny">GameVault support contact is not configured in this repository. Apply the included Supabase setup steps and configure your project’s support contact before launch.</p><a class="btn" href="/pages/account.html">Account overview</a></section></div>`},{backend:false});}

function authDestination(){
  const requested=new URLSearchParams(location.search).get('next');
  if(!requested)return location.origin+'/pages/account.html';
  try{const candidate=new URL(requested,location.origin);if(candidate.origin===location.origin&&!['/pages/login.html','/pages/signup.html'].includes(candidate.pathname))return candidate.href}catch{}
  return location.origin+'/pages/account.html';
}
function authCallbackURL(){
  const destination=new URL(authDestination());
  const callback=new URL('/pages/login.html',location.origin);
  callback.searchParams.set('next',destination.pathname+destination.search+destination.hash);
  return callback.href;
}function authProviderMarkup(configured){
  const providers=[['google','Google','G'],['apple','Apple','A'],['discord','Discord',icon('discord')],['twitch','Twitch',icon('twitch')],['azure','Microsoft account','M']];
  const initialStatus=configured?'CHECKING':'SETUP NEEDED';
  const buttons=providers.map(([id,label,mark])=>'<button class="gv-auth-provider" type="button" data-auth-provider="'+id+'" disabled title="Checking Supabase provider setup"><span class="gv-auth-provider-mark '+(id==='google'?'is-google ':'')+(id==='azure'?'is-microsoft':'')+'">'+mark+'</span><span class="gv-auth-provider-copy"><span>'+label+'</span><small class="provider-status">'+initialStatus+'</small></span></button>').join('');
  return '<div class="gv-auth-divider"><span>or continue with</span></div><div class="gv-auth-provider-grid">'+buttons+'</div><p class="form-note" id="oauth-provider-note">Social sign-in buttons are enabled only when the matching provider is active in Supabase. Microsoft account sign-in does not grant Xbox service access.</p><div class="gv-platform-login"><div class="gv-platform-login-heading"><strong>Game platform accounts</strong><span>Linking setup needed</span></div><p>These accounts may be linkable after their platform and server requirements are reviewed. GameVault never asks for your platform password.</p><div class="gv-platform-tags"><span>Steam · OpenID flow needed</span><span>Epic Games · provider setup needed</span><span>PlayStation Network · provider setup needed</span><span>Xbox · service approval needed</span><span>Rockstar Games · provider access needed</span></div></div>';
}
async function bindOAuthButtons(root,configured){
  if(!configured||!supabase)return;
  const feedback=root.querySelector('#auth-feedback');
  const note=root.querySelector('#oauth-provider-note');
  const status=await loadEnabledOAuthProviders();
  if(status.failed&&note)note.textContent='Provider status could not be checked. Email and password sign-in remain available; social buttons stay disabled until Supabase confirms setup.';
  root.querySelectorAll('[data-auth-provider]').forEach(button=>{
    const enabled=status.providers.includes(button.dataset.authProvider);
    button.disabled=!enabled;
    button.title=enabled?'Continue with '+button.dataset.authProvider:'Enable this provider in Supabase Authentication settings first';
    const state=button.querySelector('.provider-status');
    if(state)state.textContent=enabled?'READY':'SETUP NEEDED';
    if(!enabled)return;
    button.addEventListener('click',async()=>{
      button.disabled=true;
      commonFormMessage(feedback,'Connecting to '+button.dataset.authProvider+'…','info');
      try{
        const {error:authError}=await supabase.auth.signInWithOAuth({provider:button.dataset.authProvider,options:{redirectTo:authCallbackURL(),...(button.dataset.authProvider==='azure'?{scopes:'email'}:{})}});
        if(authError){commonFormMessage(feedback,authError.message,'error');button.disabled=false;}
      }catch(error){commonFormMessage(feedback,error.message||'Sign-in could not start. Try again.','error');button.disabled=false;}
    });
  });
}
async function redirectSignedInUser(configured){
  if(!configured||!supabase)return;
  const {data,error}=await supabase.auth.getSession();
  if(!error&&data.session)location.replace(authDestination());
}
function login(){entry('login',async({root,configured})=>{const schema=configured?await inspectCoreSchema():{status:'not-configured'};const canUseOAuth=configured&&schema.status==='ready';root.insertAdjacentHTML('beforeend',`<section class="surface form-card"><div class="surface-pad"><form class="form-stack" id="login-form"><label class="field-wrap">Email<input class="field" name="email" type="email" autocomplete="email" required></label><label class="field-wrap">Password<input class="field" name="password" type="password" autocomplete="current-password" required></label><div id="auth-feedback"></div><button class="btn btn-primary" ${configured?'':'disabled'}>Sign in</button>${authProviderMarkup(canUseOAuth)}<div class="row"><a class="muted tiny" href="/pages/forgot-password.html">Forgot password?</a><a class="muted tiny" href="/pages/signup.html">Create account</a></div>${!configured?'<p class="form-note">Backend not configured. Add your Supabase URL and public key to enable sign-in.</p>':''}</form></div></section>`);root.querySelector('#login-form').addEventListener('submit',async e=>{e.preventDefault();if(!configured)return;const fd=new FormData(e.currentTarget);const {error:authError}=await supabase.auth.signInWithPassword({email:fd.get('email').toString().trim(),password:fd.get('password').toString()});if(authError){commonFormMessage(root.querySelector('#auth-feedback'),authError.message,'error');return}location.href=authDestination()});bindOAuthButtons(root,canUseOAuth);await redirectSignedInUser(configured)});}

function signup(){entry('signup',async({root,configured})=>{
  const schema=configured?await inspectCoreSchema():{status:'not-configured'};
  const ready=configured&&schema.status==='ready';
  root.insertAdjacentHTML('beforeend',`<section class="surface form-card"><div class="surface-pad"><form class="form-stack" id="signup-form"><label class="field-wrap">Username<input class="field" name="username" minlength="3" maxlength="24" pattern="[A-Za-z0-9_]+" required></label><label class="field-wrap">Display name<input class="field" name="display_name" maxlength="60" required></label><label class="field-wrap">Email<input class="field" name="email" type="email" autocomplete="email" required></label><label class="field-wrap">Password<input class="field" name="password" type="password" minlength="10" autocomplete="new-password" required></label><label class="check-line"><input type="checkbox" required>I agree to the community guidelines and privacy notice.</label><div id="auth-feedback"></div><button class="btn btn-primary" ${ready?'':'disabled'}>Create account</button><button class="btn" id="resend-verification" type="button" disabled>Resend verification email</button><p class="form-note">Already submitted sign-up? Enter that email above and resend its confirmation link instead of creating another account.</p>${authProviderMarkup(ready)}<a class="muted tiny" href="/pages/login.html">Already registered? Sign in</a>${!configured?'<p class="form-note">Backend not configured. Sign-up is unavailable until Supabase is connected.</p>':''}</form></div></section>`);
  const form=root.querySelector('#signup-form');
  const feedback=root.querySelector('#auth-feedback');
  const emailField=form.elements.email;
  const resendButton=root.querySelector('#resend-verification');
  const syncResendButton=()=>{resendButton.disabled=!configured||!emailField.value.trim()||resendButton.dataset.busy==='true'};
  emailField.addEventListener('input',syncResendButton);
  form.addEventListener('submit',async e=>{
    e.preventDefault();
    if(!ready)return;
    const fd=new FormData(form);
    const email=fd.get('email').toString().trim();
    const {data,error:authError}=await supabase.auth.signUp({email,password:fd.get('password').toString(),options:{emailRedirectTo:authCallbackURL(),data:{username:fd.get('username').toString().trim().toLowerCase(),display_name:fd.get('display_name').toString().trim()}}});
    if(authError){commonFormMessage(feedback,authError.message+' If you already submitted this email, use “Resend verification email” below.','error');return}
    commonFormMessage(feedback,data.session?'Account created.':'Check your email to verify your GameVault account before signing in. If it does not arrive, check spam and use the resend button below.');
  });
  resendButton.addEventListener('click',async()=>{
    const email=emailField.value.trim();
    if(!configured||!email)return;
    resendButton.dataset.busy='true';
    syncResendButton();
    try{
      const {error:resendError}=await supabase.auth.resend({type:'signup',email,options:{emailRedirectTo:authCallbackURL()}});
      commonFormMessage(feedback,resendError?`Could not resend the link: ${resendError.message}`:'If this email has a pending sign-up, a confirmation link has been sent. Check your inbox and spam folder. If you recently requested one, wait before trying again.',resendError?'error':'success');
    }catch(error){commonFormMessage(feedback,`Could not resend the link: ${error.message||'Please try again later.'}`,'error')}
    finally{resendButton.dataset.busy='false';syncResendButton()}
  });
  syncResendButton();
  bindOAuthButtons(root,ready);
  await redirectSignedInUser(configured)
});}function forgot(){entry('forgot',async({root,configured})=>{root.insertAdjacentHTML('beforeend',`<section class="surface form-card"><div class="surface-pad"><form id="forgot-form" class="form-stack"><label class="field-wrap">Account email<input class="field" type="email" name="email" required></label><div id="auth-feedback"></div><button class="btn btn-primary" ${configured?'':'disabled'}>Send reset email</button><a class="muted tiny" href="/pages/login.html">Back to sign in</a>${!configured?'<p class="form-note">Backend not configured. Reset email is unavailable until Supabase Auth is configured.</p>':''}</form></div></section>`);root.querySelector('#forgot-form').addEventListener('submit',async e=>{e.preventDefault();if(!configured)return;const email=new FormData(e.currentTarget).get('email').toString().trim();const {error:authError}=await supabase.auth.resetPasswordForEmail(email,{redirectTo:location.origin+'/pages/reset-password.html'});commonFormMessage(root.querySelector('#auth-feedback'),authError?.message||'If the address belongs to an account, a reset link will arrive by email.',authError?'error':'success')})});}

function reset(){entry('reset',async({root,configured})=>{root.insertAdjacentHTML('beforeend',`<section class="surface form-card"><div class="surface-pad"><form id="reset-form" class="form-stack"><label class="field-wrap">New password<input class="field" type="password" name="password" minlength="10" autocomplete="new-password" required></label><label class="field-wrap">Repeat password<input class="field" type="password" name="confirm" minlength="10" autocomplete="new-password" required></label><div id="auth-feedback"></div><button class="btn btn-primary" ${configured?'':'disabled'}>Set password</button>${!configured?'<p class="form-note">Backend not configured. Password reset is unavailable.</p>':''}</form></div></section>`);root.querySelector('#reset-form').addEventListener('submit',async e=>{e.preventDefault();if(!configured)return;const fd=new FormData(e.currentTarget);if(fd.get('password')!==fd.get('confirm')){commonFormMessage(root.querySelector('#auth-feedback'),'Passwords do not match.','error');return}const {error:authError}=await supabase.auth.updateUser({password:fd.get('password').toString()});if(authError)commonFormMessage(root.querySelector('#auth-feedback'),authError.message,'error');else{commonFormMessage(root.querySelector('#auth-feedback'),'Password changed. You can sign in now.');setTimeout(()=>location.href='/pages/login.html',1800)}})});}

const initMap={home,explore,communities,community,profile,creators,media,streams,messages,notifications,challenges,history:historyPage,account,'account-profile':accountProfile,'account-privacy':accountPrivacy,'account-security':accountSecurity,'account-notifications':accountNotifications,'account-games':accountGames,'account-delete':accountDelete,settings,moderation,guidelines:help,login,signup,forgot,reset};
export function initFeature(name){(initMap[name]||home)()}
